/* Banque de fiches finance de Steve. Genere par build_fiches.py, ne pas editer a la main.
   Mise a jour hebdomadaire : on regenere ce fichier et on bumpe le cache du service worker. */
const FICHES = {"maj":"2026-09-21","themes":{"cdg":"Contrôle de gestion","cpt":"Comptabilité et clôture","audit":"Audit et contrôle interne","af":"Analyse financière","cf":"Corporate finance","tres":"Trésorerie et BFR","conso":"Consolidation et normes","fisc":"Fiscalité","mkt":"Marchés et produits","macro":"Macro et actualité","reg":"Banque, assurance, régulation","data":"Outils et data","meta":"Métier, entretien, anglais"},"fiches":[{"t":"cdg","q":"Quelle est la différence entre un budget et un forecast ?","r":"Le budget est figé en début d'année, le forecast est réactualisé en cours d'année avec ce qu'on sait maintenant.","x":"En entretien : le budget sert à juger la performance, le forecast sert à piloter. On ne remplace jamais le budget par le forecast, sinon plus personne n'est comptable de son écart."},{"t":"cdg","q":"Qu'est-ce qu'un écart sur volume et un écart sur prix ?","r":"Volume = (quantité réelle moins quantité prévue) x prix prévu. Prix = (prix réel moins prix prévu) x quantité réelle.","x":"La règle : on fige toujours l'autre facteur à son niveau prévu pour le premier écart, et au niveau réel pour le second. Sinon on compte deux fois l'effet croisé."},{"t":"cdg","q":"Qu'est-ce qu'un coût standard ?","r":"Un coût de référence calculé à l'avance pour une unité produite, servant de norme pour mesurer les écarts.","x":"Il vieillit vite. Un coût standard qui n'a pas été révisé depuis deux ans fabrique des écarts qui ne veulent rien dire."},{"t":"cdg","q":"Charges fixes et charges variables, comment on les sépare vraiment ?","r":"Les variables bougent avec le volume d'activité, les fixes non, sur la plage d'activité considérée.","x":"Le mot qui compte est « sur la plage ». Un loyer est fixe jusqu'au jour où il faut un deuxième entrepôt. On parle de charges fixes par paliers."},{"t":"cdg","q":"Comment se calcule le seuil de rentabilité ?","r":"Charges fixes divisées par le taux de marge sur coût variable.","x":"Le taux de marge sur coût variable, c'est la marge sur coût variable divisée par le chiffre d'affaires. Retenir : combien il reste sur 1 euro vendu pour payer les fixes."},{"t":"cdg","q":"Qu'est-ce que le levier opérationnel ?","r":"La sensibilité du résultat d'exploitation à une variation du chiffre d'affaires. Plus les charges fixes pèsent, plus le levier est fort.","x":"Levier fort = très rentable quand ça monte, très douloureux quand ça baisse. C'est le cas d'une usine, pas d'une société de conseil."},{"t":"cdg","q":"Quelle différence entre marge sur coût variable et marge brute ?","r":"La marge sur coût variable retire tous les coûts variables. La marge brute retire le coût des ventes, qui peut contenir du fixe.","x":"Piège d'entretien classique. La marge brute est comptable, la marge sur coût variable est un outil de gestion."},{"t":"cdg","q":"Qu'est-ce qu'un centre de coût, un centre de profit, un centre d'investissement ?","r":"Coût : responsable des dépenses seulement. Profit : responsable des recettes et des dépenses. Investissement : responsable en plus du capital employé.","x":"On ne juge jamais un responsable sur ce qu'il ne pilote pas. C'est le principe de contrôlabilité."},{"t":"cdg","q":"Qu'est-ce que la méthode ABC en contrôle de gestion ?","r":"Activity Based Costing : on affecte les charges indirectes aux produits via les activités qui les consomment réellement.","x":"Utile quand les charges indirectes sont lourdes et les produits très différents. Coûteuse à maintenir, beaucoup d'entreprises l'abandonnent après deux ans."},{"t":"cdg","q":"Comment répartir des charges indirectes sans méthode ABC ?","r":"Par des clés de répartition : surface, effectif, heures machine, chiffre d'affaires.","x":"Toujours dire quelle clé et pourquoi. Une clé au chiffre d'affaires fait porter les frais de siège aux gros produits, ce qui n'est pas toujours juste."},{"t":"cdg","q":"Qu'est-ce que le taux d'activité, ou taux d'utilisation, dans le conseil ?","r":"Jours facturés divisés par jours ouvrés disponibles. C'est le premier indicateur de rentabilité d'une société de services.","x":"Attention au dénominateur. Certains comptent les congés dedans, d'autres non, et le taux passe de 75 à 85 pour cent sans qu'il se soit rien passé."},{"t":"cdg","q":"Qu'est-ce que le TJM et pourquoi il ne suffit pas ?","r":"Taux journalier moyen facturé. Il ne dit rien tant qu'on ne le compare pas au coût journalier du consultant.","x":"La marge par affaire, c'est TJM vendu moins coût complet journalier, multiplié par le nombre de jours. Un TJM élevé sur un consultant cher peut rapporter moins qu'un TJM moyen sur un junior."},{"t":"cdg","q":"À quoi sert un tableau de bord par rapport à un reporting ?","r":"Le reporting rend compte du passé, le tableau de bord sert à décider maintenant. Le premier est exhaustif, le second est court.","x":"Bonne réponse en entretien : un tableau de bord tient sur une page et contient des indicateurs sur lesquels quelqu'un peut agir dès demain."},{"t":"cdg","q":"Qu'est-ce qu'un KPI avancé et un KPI retardé ?","r":"Avancé, ou leading : il annonce ce qui va arriver, comme le carnet de commandes. Retardé, ou lagging : il constate, comme le chiffre d'affaires.","x":"Un tableau de bord qui n'a que des indicateurs retardés est un rétroviseur. Il faut au moins un avancé par processus."},{"t":"cdg","q":"Qu'est-ce que le rolling forecast ?","r":"Une prévision glissante, souvent sur douze mois, réactualisée chaque mois ou chaque trimestre.","x":"L'avantage : l'horizon ne se rétrécit jamais. En décembre, un budget classique ne voit plus qu'un mois devant, un rolling forecast voit toujours douze."},{"t":"cdg","q":"Qu'est-ce que le budget base zéro ?","r":"On repart de zéro chaque année et chaque ligne doit être justifiée, au lieu de reprendre l'an dernier plus un pourcentage.","x":"Très efficace une fois, épuisant tous les ans. Beaucoup de groupes le font sur un périmètre à la fois, par rotation."},{"t":"cdg","q":"Comment justifier un écart budgétaire en trois phrases ?","r":"Le chiffre et son écart, la cause principale, l'action décidée avec une date.","x":"Ne jamais s'arrêter à la cause. Un écart commenté sans action à côté, c'est du commentaire de match."},{"t":"cdg","q":"Qu'est-ce qu'un coût complet et un coût partiel ?","r":"Complet : on affecte toutes les charges, directes et indirectes. Partiel : on ne retient que les charges pertinentes pour la décision.","x":"Pour décider d'accepter une commande supplémentaire, on raisonne en coût partiel. Les fixes sont déjà payés, ils ne doivent pas tuer la décision."},{"t":"cdg","q":"Qu'est-ce qu'un coût irrécupérable, ou sunk cost ?","r":"Une dépense déjà engagée qu'aucune décision future ne peut récupérer.","x":"Elle ne doit jamais entrer dans une décision. C'est le piège le plus courant en comité : on continue un projet parce qu'on a déjà dépensé, pas parce qu'il rapporte."},{"t":"cdg","q":"Qu'est-ce que le coût d'opportunité ?","r":"Ce qu'on renonce à gagner en choisissant une option plutôt qu'une autre.","x":"Il n'apparaît dans aucune comptabilité. C'est justement pour ça que le contrôleur de gestion doit le nommer."},{"t":"cdg","q":"Comment décide-t-on de faire ou de faire faire ?","r":"On compare le coût pertinent en interne, hors coûts fixes non évitables, au prix externe, en ajoutant les coûts de pilotage du prestataire.","x":"L'erreur classique : comparer un coût complet interne à un prix externe. On surestime alors l'intérêt d'externaliser."},{"t":"cdg","q":"Qu'est-ce qu'un prix de cession interne ?","r":"Le prix auquel une entité du groupe facture une autre entité du groupe.","x":"Il change le résultat de chacune sans changer celui du groupe. Il a donc des enjeux fiscaux, et l'administration regarde s'il est de pleine concurrence."},{"t":"cdg","q":"Qu'est-ce que le ROI et sa limite ?","r":"Résultat divisé par le capital investi. Il ne dit rien du temps ni du risque.","x":"Deux projets à 20 pour cent de ROI ne se valent pas si l'un rend l'argent en un an et l'autre en huit."},{"t":"cdg","q":"Qu'est-ce que le payback, ou délai de récupération ?","r":"Le nombre d'années au bout duquel les flux cumulés remboursent l'investissement.","x":"Simple et parlant, mais il ignore tout ce qui se passe après. Un bon complément à la VAN, jamais un remplacement."},{"t":"cdg","q":"Quelle est la différence entre CAPEX et OPEX ?","r":"CAPEX : dépense d'investissement, immobilisée au bilan puis amortie. OPEX : dépense d'exploitation, passée en charge tout de suite.","x":"Le passage au cloud a transformé des CAPEX en OPEX. Ça dégrade l'EBITDA à périmètre identique, il faut le dire avant qu'on vous le reproche."},{"t":"cdg","q":"Qu'est-ce qu'un business plan et sur quoi il se juge ?","r":"Une projection chiffrée sur trois à cinq ans. Il se juge sur ses hypothèses, pas sur ses chiffres.","x":"Toujours livrer un business plan avec la liste de ses trois hypothèses les plus sensibles et ce qui se passe si elles bougent de dix pour cent."},{"t":"cdg","q":"Qu'est-ce qu'une analyse de sensibilité ?","r":"On fait bouger une hypothèse à la fois pour voir de combien le résultat change.","x":"À ne pas confondre avec un scénario, où plusieurs hypothèses bougent ensemble de façon cohérente."},{"t":"cdg","q":"Comment construit-on un scénario pessimiste crédible ?","r":"On prend les hypothèses qui se dégradent ensemble dans la vraie vie : moins de volume, plus de coûts d'achat, délais de paiement plus longs.","x":"Un scénario où seul le chiffre d'affaires baisse n'arrive jamais. C'est le signe qu'il a été fabriqué pour rassurer."},{"t":"cdg","q":"Qu'est-ce que le carnet de commandes et le backlog ?","r":"Le total signé pas encore réalisé. C'est le meilleur indicateur avancé d'une société de projets.","x":"À rapprocher du chiffre d'affaires mensuel : le backlog exprimé en mois d'activité dit combien de temps on tient sans rien vendre de nouveau."},{"t":"cdg","q":"Qu'est-ce que le taux de marge et le taux de marque ?","r":"Marge : marge divisée par le coût d'achat. Marque : marge divisée par le prix de vente.","x":"Piège de test de recrutement. 50 pour cent de marge, c'est 33 pour cent de marque. Ne jamais répondre sans avoir vérifié le dénominateur."},{"t":"cdg","q":"Qu'est-ce que le mix produit et pourquoi il explique tant d'écarts ?","r":"La répartition des ventes entre produits. Vendre autant mais autrement change la marge sans changer le volume.","x":"Quand le chiffre d'affaires est conforme et la marge en baisse, cherchez le mix avant de chercher le prix."},{"t":"cdg","q":"Qu'est-ce que la comptabilité analytique ?","r":"Une comptabilité interne qui réaffecte les charges par destination : produit, client, projet, agence.","x":"Elle n'est pas normée, donc chaque entreprise a la sienne. Le premier travail dans un nouveau poste, c'est de comprendre ses conventions."},{"t":"cdg","q":"Qu'est-ce qu'un axe analytique ?","r":"Une dimension de découpage de la charge : centre de coût, projet, client, nature.","x":"Trop d'axes tuent l'analytique. Trois axes bien tenus valent mieux que sept mal renseignés."},{"t":"cdg","q":"Qu'est-ce que la contribution d'un produit ?","r":"Son chiffre d'affaires moins ses coûts variables, donc ce qu'il apporte pour couvrir les fixes.","x":"Un produit dont la contribution est positive mérite d'être gardé même s'il est en perte en coût complet, tant qu'il y a de la capacité libre."},{"t":"cdg","q":"Comment mesure-t-on la performance d'un commercial correctement ?","r":"Sur la marge apportée, pas sur le chiffre d'affaires signé.","x":"Payer un commercial au chiffre d'affaires, c'est financer les remises qu'il accorde."},{"t":"cdg","q":"Qu'est-ce que la productivité et à quoi la comparer ?","r":"Un volume produit rapporté à un moyen consommé, heures ou effectifs. Elle ne veut rien dire seule, il faut une série dans le temps.","x":"Toujours donner la productivité avec sa base : par heure, par ETP, par machine."},{"t":"cdg","q":"Qu'est-ce qu'un ETP ?","r":"Équivalent temps plein. Deux mi-temps font un ETP.","x":"Base indispensable pour comparer des équipes. Une masse salariale qui monte de 5 pour cent avec un ETP en hausse de 5 pour cent, c'est un effectif, pas une inflation."},{"t":"cdg","q":"Comment expliquer une hausse de masse salariale ?","r":"Trois effets : effet effectif, effet salaire moyen, effet structure ou mix de qualification.","x":"C'est le même raisonnement que volume, prix, mix. Décomposer d'abord, commenter ensuite."},{"t":"cdg","q":"Qu'est-ce que l'effet report en masse salariale ?","r":"L'impact sur l'année N des augmentations accordées en cours d'année N moins 1.","x":"Il tombe même sans aucune décision nouvelle. C'est ce qui surprend les budgets construits en oubliant le calendrier des augmentations."},{"t":"cdg","q":"Qu'est-ce que le GVT ?","r":"Glissement Vieillesse Technicité : l'évolution automatique de la masse salariale liée à l'ancienneté et aux promotions.","x":"Vocabulaire du secteur public et des grands groupes. Le connaître donne un vrai signal en entretien."},{"t":"cdg","q":"Qu'est-ce qu'un provisionnement de fin de mois et pourquoi il compte ?","r":"On enregistre les charges consommées mais non facturées, pour que le mois porte ses vrais coûts.","x":"Sans cut-off correct, un mois paraît excellent et le suivant catastrophique. C'est la première chose à vérifier dans un reporting qu'on reprend."},{"t":"cdg","q":"Qu'est-ce qu'une FNP et une CCA ?","r":"FNP : facture non parvenue, charge reçue non facturée. CCA : charge constatée d'avance, facture reçue pour une période future.","x":"Les deux servent au cut-off, dans deux sens opposés. Une FNP augmente la charge du mois, une CCA la diminue."},{"t":"cdg","q":"Qu'est-ce qu'une FAE et un PCA ?","r":"FAE : facture à établir, produit acquis non facturé. PCA : produit constaté d'avance, facturé pour une période future.","x":"Symétrique des FNP et CCA, côté produits. Un abonnement annuel encaissé en janvier est un PCA sur onze douzièmes."},{"t":"cdg","q":"Comment sait-on qu'un reporting est fiable ?","r":"Il se réconcilie avec la comptabilité, il se produit toujours à la même date, et deux personnes différentes obtiennent le même chiffre.","x":"C'est le triptyque à citer en entretien : réconcilié, daté, reproductible."},{"t":"cdg","q":"Qu'est-ce que la réconciliation entre analytique et comptabilité générale ?","r":"On vérifie que la somme des montants ventilés par axe égale le solde du compte général.","x":"L'écart vient presque toujours des mêmes endroits : écritures sans axe, écritures d'OD passées après coup, comptes de transit."},{"t":"cdg","q":"Qu'est-ce qu'un compte de transit et pourquoi il est dangereux ?","r":"Un compte d'attente où l'on pose ce qu'on ne sait pas encore imputer.","x":"Il doit être à zéro à chaque clôture. Un compte d'attente qui ne bouge plus depuis six mois cache une erreur, jamais une attente."},{"t":"cdg","q":"Qu'est-ce que la clôture rapide, ou fast close ?","r":"Un processus qui sort les comptes en quelques jours grâce à des estimations cadrées et des tâches parallélisées.","x":"Le prix à payer est un peu de précision. On l'accepte parce qu'un chiffre à J plus 5 sert à décider, un chiffre parfait à J plus 25 ne sert plus à rien."},{"t":"cdg","q":"Qu'est-ce qu'un contrôle de premier niveau ?","r":"Un contrôle fait par celui qui produit, intégré à son travail, avant toute revue extérieure.","x":"Trois lignes de défense : l'opérationnel, le contrôle indépendant, l'audit interne. Savoir les nommer vaut des points."},{"t":"cdg","q":"Comment présenter un chiffre à un dirigeant qui n'est pas financier ?","r":"Le chiffre, la comparaison qui lui donne du sens, la cause, la décision proposée.","x":"Jamais plus de trois chiffres dans une phrase. Un dirigeant retient un ordre de grandeur et une décision, pas une ligne de tableau."},{"t":"cdg","q":"Qu'est-ce qu'une re-prévision, ou reforecast ?","r":"La mise à jour de l'atterrissage annuel avec le réalisé connu plus le reste à faire.","x":"Formule mentale : réalisé à date plus prévision du reste de l'année. On ne recalcule jamais les mois déjà passés."},{"t":"cdg","q":"Qu'est-ce que l'atterrissage ?","r":"Le résultat attendu à la fin de l'exercice compte tenu de ce qui s'est déjà passé.","x":"C'est le mot que les directions utilisent. Savoir dire « l'atterrissage est à tant » vous place tout de suite dans le métier."},{"t":"cdg","q":"Qu'est-ce qu'un plan d'action correctif ?","r":"Une liste courte d'actions, chacune avec un responsable, une date et un montant attendu.","x":"Sans montant attendu, on ne pourra jamais dire si l'action a marché."},{"t":"cdg","q":"Que regarde-t-on en premier dans un P&L qu'on découvre ?","r":"La marge brute en pourcentage et son évolution, puis le poids des charges de personnel.","x":"Ces deux lignes expliquent la majorité des surprises. Le reste vient après."},{"t":"cdg","q":"Qu'est-ce que le principe de contrôlabilité ?","r":"On ne juge un responsable que sur ce qu'il peut influencer.","x":"C'est ce qui justifie de sortir les frais de siège des résultats d'agence, ou au moins de les montrer sur une ligne séparée."},{"t":"cdg","q":"Comment fiabiliser un fichier de reporting qui circule par mail ?","r":"On le remplace par une source unique alimentée automatiquement, et on verrouille les saisies.","x":"Le vrai problème d'un fichier qui circule n'est pas la formule, c'est qu'il existe en douze versions."},{"t":"cpt","q":"Quelle est la différence entre le bilan et le compte de résultat ?","r":"Le bilan est une photo à une date. Le compte de résultat est un film sur une période.","x":"Les deux se rejoignent par le résultat, qui apparaît au passif du bilan. Si on vous demande le lien, c'est la réponse."},{"t":"cpt","q":"Que trouve-t-on à l'actif et au passif ?","r":"À l'actif, ce que l'entreprise possède et utilise. Au passif, d'où vient l'argent : capitaux propres et dettes.","x":"Formulation qui marque : l'actif dit ce qu'on en fait, le passif dit à qui c'est."},{"t":"cpt","q":"Qu'est-ce que la partie double ?","r":"Toute écriture équilibre un débit et un crédit du même montant.","x":"Le corollaire utile : si le bilan ne s'équilibre pas, ce n'est pas le bilan qui a un problème, c'est une écriture qui a été forcée."},{"t":"cpt","q":"Que veut dire débiter et créditer un compte de charge ?","r":"On débite une charge pour l'augmenter, on la crédite pour l'annuler.","x":"Moyen mnémotechnique : charges et actifs augmentent au débit, produits, dettes et capitaux propres augmentent au crédit."},{"t":"cpt","q":"Qu'est-ce qu'un amortissement ?","r":"La constatation comptable de la perte de valeur d'une immobilisation liée à son usage, étalée sur sa durée d'utilisation.","x":"Ce n'est pas une sortie d'argent. C'est pour ça qu'on le rajoute au résultat pour calculer la capacité d'autofinancement."},{"t":"cpt","q":"Amortissement linéaire ou dégressif, quelle différence ?","r":"Linéaire : le même montant chaque année. Dégressif : plus fort au début, il suit mieux la perte de valeur réelle et donne un avantage fiscal immédiat.","x":"Le dégressif est un choix fiscal encadré, réservé à certains biens. Il ne change pas le total amorti, seulement son rythme."},{"t":"cpt","q":"Qu'est-ce qu'une provision ?","r":"Une charge probable dont le montant ou l'échéance est incertain, comptabilisée quand l'obligation existe déjà.","x":"Les trois conditions : obligation à la clôture, sortie de ressources probable, estimation fiable. Sans les trois, c'est un engagement hors bilan."},{"t":"cpt","q":"Quelle différence entre provision et dépréciation ?","r":"La provision est au passif, elle couvre une dette probable. La dépréciation est à l'actif, elle constate qu'un actif vaut moins.","x":"Confusion très fréquente en entretien. Créance douteuse : c'est une dépréciation, pas une provision."},{"t":"cpt","q":"Qu'est-ce qu'une charge à payer ?","r":"Une charge certaine dans son principe et son montant, mais pas encore facturée à la clôture.","x":"Différence avec la provision : ici il n'y a plus d'incertitude, juste un papier qui manque."},{"t":"cpt","q":"Qu'est-ce que le principe de séparation des exercices, ou cut-off ?","r":"Chaque charge et chaque produit doit être rattaché à la période où il a été consommé ou acquis, pas à la date de la facture.","x":"C'est le principe le plus testé en entretien de clôture, et la première source d'erreur en pratique."},{"t":"cpt","q":"Qu'est-ce que le principe de prudence ?","r":"On comptabilise les pertes probables dès qu'on les connaît, mais les gains seulement quand ils sont réalisés.","x":"C'est ce qui explique qu'on déprécie une créance douteuse sans jamais réévaluer un stock à la hausse en normes françaises."},{"t":"cpt","q":"Qu'est-ce que le principe de continuité d'exploitation ?","r":"On établit les comptes en supposant que l'entreprise poursuivra son activité.","x":"S'il y a doute, les valeurs changent de base : on passe en valeur liquidative et l'annexe doit le dire. C'est un sujet d'alerte pour le commissaire aux comptes."},{"t":"cpt","q":"Qu'est-ce que la CAF ?","r":"Capacité d'autofinancement : le résultat net plus les charges non décaissées, moins les produits non encaissés.","x":"Vite fait de tête : résultat net plus dotations aux amortissements et provisions, moins reprises, corrigé des plus et moins-values de cession."},{"t":"cpt","q":"Qu'est-ce que l'EBE ?","r":"Excédent brut d'exploitation : la valeur ajoutée plus les subventions d'exploitation, moins les impôts et taxes et les charges de personnel.","x":"C'est le résultat avant toute politique d'amortissement, de financement et de fiscalité. L'équivalent français le plus proche de l'EBITDA."},{"t":"cpt","q":"Qu'est-ce que la valeur ajoutée ?","r":"La production de l'exercice moins les consommations en provenance des tiers.","x":"Elle dit ce que l'entreprise crée elle-même. Une valeur ajoutée faible sur un chiffre d'affaires élevé signale un négociant ou un assembleur."},{"t":"cpt","q":"Quels sont les soldes intermédiaires de gestion, dans l'ordre ?","r":"Marge commerciale, production de l'exercice, valeur ajoutée, EBE, résultat d'exploitation, résultat courant avant impôt, résultat net.","x":"Les réciter dans l'ordre est un classique d'entretien junior. Chacun retire une famille de charges de plus."},{"t":"cpt","q":"Qu'est-ce que le résultat exceptionnel ?","r":"Ce qui ne relève ni de l'exploitation ni du financement : cessions d'actifs, litiges, restructurations.","x":"Il a disparu des normes IFRS. En normes françaises il existe encore, et il sert parfois à embellir un exercice. Toujours le regarder."},{"t":"cpt","q":"Qu'est-ce qu'un compte de régularisation ?","r":"Un compte qui décale une charge ou un produit dans le temps pour respecter le cut-off.","x":"Classe 48 au plan comptable général. Un solde important en fin d'année mérite toujours une explication."},{"t":"cpt","q":"À quoi servent les classes 1 à 7 du plan comptable ?","r":"1 capitaux, 2 immobilisations, 3 stocks, 4 tiers, 5 financier, 6 charges, 7 produits.","x":"Les classes 1 à 5 font le bilan, les classes 6 et 7 font le compte de résultat. Le savoir permet de lire une balance sans plan de comptes."},{"t":"cpt","q":"Qu'est-ce qu'une balance générale ?","r":"La liste de tous les comptes avec leur total débit, total crédit et solde à une date.","x":"C'est le document à demander en premier quand on reprend une comptabilité. Le grand livre vient après, pour le détail."},{"t":"cpt","q":"Qu'est-ce que le lettrage ?","r":"L'action de rapprocher une facture et son règlement dans un compte de tiers.","x":"Un compte client non lettré ne veut pas dire impayé. Ça veut souvent dire qu'un règlement global n'a pas été ventilé."},{"t":"cpt","q":"Qu'est-ce qu'un rapprochement bancaire ?","r":"La comparaison entre le compte 512 de la comptabilité et le relevé de banque, en expliquant chaque écart.","x":"Les écarts normaux sont les chèques non débités et les remises non créditées. Tout le reste est une erreur à corriger."},{"t":"cpt","q":"Qu'est-ce qu'un FEC ?","r":"Fichier des écritures comptables, format légal obligatoire, remis à l'administration en cas de contrôle.","x":"C'est aussi le meilleur fichier de travail : dix-huit colonnes normées, toutes les écritures de l'exercice, lisible dans n'importe quel outil."},{"t":"cpt","q":"Qu'est-ce qu'un journal comptable ?","r":"Un regroupement d'écritures par nature : achats, ventes, banque, paie, opérations diverses.","x":"Le journal d'OD est celui à surveiller. C'est là que passent les corrections, donc là que se cachent les erreurs."},{"t":"cpt","q":"Qu'est-ce que le report à nouveau ?","r":"Le solde d'ouverture d'un compte, repris de l'exercice précédent.","x":"Piège classique : lire le solde d'un compte sur les seuls mouvements de l'année en oubliant le report. Le solde réel est report plus mouvements."},{"t":"cpt","q":"Comment affecte-t-on le résultat d'un exercice clos ?","r":"En assemblée : réserve légale jusqu'à 10 pour cent du capital, puis réserves, dividendes ou report à nouveau.","x":"La réserve légale est obligatoire tant que le plafond n'est pas atteint. C'est une question fréquente en entretien PME."},{"t":"cpt","q":"Qu'est-ce qu'un compte courant d'associé ?","r":"Une avance de trésorerie faite par un associé à la société, remboursable.","x":"C'est une dette, pas du capital. Un compte courant débiteur, donc l'associé qui doit à la société, est interdit pour les personnes physiques dans une SA ou une SARL."},{"t":"cpt","q":"Qu'est-ce que l'annexe des comptes ?","r":"Le document qui explique les règles et méthodes retenues et détaille les postes significatifs.","x":"C'est là que se lisent les vrais choix comptables. Un analyste expérimenté commence souvent par l'annexe."},{"t":"cpt","q":"Quelle différence entre expert-comptable et commissaire aux comptes ?","r":"L'expert-comptable produit et conseille. Le commissaire aux comptes certifie, il est indépendant et nommé pour six ans.","x":"Ils ne peuvent pas être la même personne sur la même entité. C'est l'incompatibilité de base."},{"t":"cpt","q":"Qu'est-ce qu'une certification avec réserve ?","r":"Le commissaire aux comptes certifie mais signale un désaccord ou une limitation d'étendue chiffrable.","x":"Trois niveaux : sans réserve, avec réserve, refus de certifier. Le refus est très rare et très grave."},{"t":"cpt","q":"Qu'est-ce qu'une immobilisation incorporelle ?","r":"Un actif sans substance physique : logiciel, brevet, marque, fonds de commerce.","x":"Le goodwill en fait partie en consolidation. En normes françaises il s'amortit, en IFRS il se teste chaque année."},{"t":"cpt","q":"Qu'est-ce qu'un test de dépréciation ?","r":"On compare la valeur comptable d'un actif à sa valeur recouvrable, et on déprécie l'écart.","x":"La valeur recouvrable est le maximum entre la valeur d'usage, calculée par les flux futurs, et la juste valeur nette des coûts de sortie."},{"t":"cpt","q":"Qu'est-ce que la valeur nette comptable ?","r":"Le coût d'acquisition moins les amortissements et dépréciations cumulés.","x":"À ne pas confondre avec la valeur de marché. Un immeuble amorti depuis vingt ans a une VNC faible et une valeur réelle élevée."},{"t":"cpt","q":"Comment comptabilise-t-on une cession d'immobilisation ?","r":"On sort la valeur brute et les amortissements, on constate le prix de vente, et l'écart est une plus ou moins-value.","x":"Elle atterrit en résultat exceptionnel en normes françaises. Pensez à la sortir avant de comparer deux exercices."},{"t":"cpt","q":"Qu'est-ce qu'un crédit-bail et comment il se traite ?","r":"Une location avec option d'achat. En normes françaises il reste hors bilan, en IFRS 16 il est au bilan comme un droit d'utilisation.","x":"C'est une des grandes divergences entre les deux référentiels. Elle change l'endettement affiché et donc les ratios."},{"t":"cpt","q":"Qu'est-ce qu'un engagement hors bilan ?","r":"Un engagement pris qui n'apparaît pas au bilan : cautions, garanties, nantissements, commandes fermes.","x":"Il est dans l'annexe. Un analyste qui l'ignore peut sous-estimer lourdement le risque réel."},{"t":"cpt","q":"Qu'est-ce que la méthode à l'avancement ?","r":"On reconnaît le chiffre d'affaires d'un contrat long au fur et à mesure de sa réalisation.","x":"L'avancement se mesure souvent par les coûts engagés sur coûts totaux prévus. Le risque : sous-estimer les coûts restants gonfle le résultat."},{"t":"cpt","q":"Qu'est-ce qu'une écriture d'OD ?","r":"Opération diverse : une écriture qui ne passe par aucun journal automatique, saisie à la main.","x":"C'est le journal à contrôler en priorité dans un audit. Toute correction y transite."},{"t":"cpt","q":"Qu'est-ce que le grand livre ?","r":"Le détail de toutes les écritures compte par compte.","x":"Balance pour voir les soldes, grand livre pour comprendre pourquoi. On passe de l'un à l'autre en permanence."},{"t":"cpt","q":"Qu'est-ce qu'un stock et comment on le valorise ?","r":"Les biens détenus pour être vendus ou consommés. Valorisés au coût d'acquisition ou de production, méthode CMUP ou FIFO.","x":"Le LIFO est interdit en IFRS et en normes françaises. Le citer comme option est une erreur classique."},{"t":"cpt","q":"Qu'est-ce que le CMUP ?","r":"Coût moyen unitaire pondéré : on recalcule un coût moyen à chaque entrée en stock.","x":"Il lisse les variations de prix. Le FIFO, lui, laisse apparaître la hausse des prix plus vite dans le coût des ventes."},{"t":"cpt","q":"Qu'est-ce qu'une variation de stock et où elle apparaît ?","r":"La différence entre stock d'ouverture et stock de clôture. Elle corrige les achats pour obtenir la consommation.","x":"Une hausse de stock diminue la charge de l'exercice. C'est un levier bien connu pour améliorer un résultat, donc à regarder."},{"t":"cpt","q":"Qu'est-ce que la TVA collectée et la TVA déductible ?","r":"Collectée : celle facturée aux clients. Déductible : celle payée aux fournisseurs. On reverse la différence.","x":"L'entreprise n'est qu'un collecteur. Si le solde est négatif, on est en crédit de TVA, remboursable ou reportable."},{"t":"cpt","q":"Quel est le fait générateur de la TVA sur les prestations de services ?","r":"L'encaissement du prix, sauf option pour les débits.","x":"Sur les biens, c'est la livraison. Cette différence est une question d'entretien fréquente et une source d'erreur réelle."},{"t":"cpt","q":"Qu'est-ce que l'autoliquidation de la TVA ?","r":"C'est le client qui déclare la TVA à la place du fournisseur, notamment sur les achats intracommunautaires et la sous-traitance du bâtiment.","x":"Effet neutre en trésorerie : on collecte et on déduit le même montant. Mais l'oubli déclaratif est sanctionné."},{"t":"cpt","q":"Qu'est-ce qu'un contrôle de cohérence sur une balance ?","r":"On vérifie que le total des débits égale le total des crédits, et que les comptes de bilan et de résultat se recoupent avec le résultat.","x":"Trois minutes de contrôle qui évitent des heures d'analyse sur des chiffres faux."},{"t":"cpt","q":"Qu'est-ce qu'un compte 471 et pourquoi il inquiète ?","r":"Un compte d'attente. Il accueille ce qu'on n'a pas su imputer.","x":"Il doit être soldé à chaque clôture. Un 471 qui traîne est un signal de désorganisation, et l'auditeur ira droit dessus."},{"t":"cpt","q":"Comment traite-t-on une créance devenue irrécouvrable ?","r":"On constate une perte sur créance irrécouvrable et on récupère la TVA, à condition de prouver le caractère définitif.","x":"À distinguer de la simple dépréciation, qui est réversible. Ici la créance sort définitivement du bilan."},{"t":"cpt","q":"Qu'est-ce que la clôture annuelle par rapport à la clôture mensuelle ?","r":"Mêmes principes, profondeur différente : inventaire physique, justification de tous les comptes, annexe, arrêté par les dirigeants.","x":"Une bonne clôture mensuelle rend la clôture annuelle presque routinière. C'est l'argument à donner pour justifier le temps passé chaque mois."},{"t":"cpt","q":"Qu'est-ce qu'un dossier de révision ?","r":"Le classeur qui justifie chaque solde de la balance par une pièce ou un calcul.","x":"La règle : un solde sans justificatif est un solde faux tant que le contraire n'est pas prouvé."},{"t":"cpt","q":"Qu'est-ce que la liasse fiscale ?","r":"L'ensemble des tableaux à transmettre à l'administration : bilan, compte de résultat, annexes et tableaux de passage.","x":"Le tableau 2058-A fait le pont entre le résultat comptable et le résultat fiscal. C'est celui qu'on vous demandera d'expliquer."},{"t":"cpt","q":"Qu'est-ce qu'une immobilisation en cours ?","r":"Un investissement engagé mais pas encore mis en service, donc pas encore amorti.","x":"Compte 23. À surveiller : un projet qui reste en cours pendant trois ans échappe à l'amortissement et gonfle l'actif."},{"t":"cpt","q":"Quelle est la durée de conservation des pièces comptables ?","r":"Dix ans pour les livres et pièces justificatives.","x":"Six ans seulement pour le contrôle fiscal, mais dix ans côté commercial. Retenir dix, c'est toujours juste."},{"t":"af","q":"Par quoi commence une analyse financière sérieuse ?","r":"Par l'activité et le modèle économique, pas par les ratios. On comprend d'abord comment la boîte gagne de l'argent.","x":"Un ratio n'a de sens que comparé à son secteur. 5 pour cent de marge nette est excellent en distribution et faible en logiciel."},{"t":"af","q":"Qu'est-ce que la marge d'exploitation ?","r":"Résultat d'exploitation divisé par le chiffre d'affaires.","x":"C'est la rentabilité du métier, avant le financement et l'impôt. Le premier ratio à regarder sur trois ans."},{"t":"af","q":"Qu'est-ce que la marge nette ?","r":"Résultat net divisé par le chiffre d'affaires.","x":"Elle mélange l'exploitation, la finance, l'exceptionnel et l'impôt. Utile pour l'actionnaire, mauvaise pour juger l'opérationnel."},{"t":"af","q":"Qu'est-ce que le ROE ?","r":"Return on equity : résultat net divisé par les capitaux propres.","x":"Un ROE élevé peut venir d'une bonne rentabilité ou simplement de beaucoup de dette. Toujours le décomposer avant de s'enthousiasmer."},{"t":"af","q":"Qu'est-ce que la décomposition de Dupont ?","r":"ROE = marge nette x rotation de l'actif x levier financier.","x":"C'est la façon de dire d'où vient la rentabilité : des prix, de l'efficacité, ou de l'endettement. Très apprécié en entretien."},{"t":"af","q":"Qu'est-ce que le ROCE ?","r":"Return on capital employed : résultat d'exploitation après impôt divisé par les capitaux employés.","x":"Capitaux employés = immobilisations plus BFR. C'est le ratio préféré des industriels parce qu'il est indépendant du financement."},{"t":"af","q":"Qu'est-ce que le ROA ?","r":"Return on assets : résultat rapporté au total de l'actif.","x":"Il pénalise les entreprises à actifs lourds. À manier seulement à l'intérieur d'un même secteur."},{"t":"af","q":"Qu'est-ce que le gearing ?","r":"Dette financière nette divisée par les capitaux propres.","x":"Au-delà de 1, l'entreprise doit plus qu'elle ne possède en propre. Les banques regardent ce ratio en priorité dans les covenants."},{"t":"af","q":"Qu'est-ce que le levier d'endettement, ou leverage ?","r":"Dette financière nette divisée par l'EBITDA.","x":"Repère de marché : au-delà de 3 ou 4 fois, le crédit devient cher. C'est le ratio de covenant le plus courant."},{"t":"af","q":"Qu'est-ce que la dette financière nette ?","r":"Dettes financières moins la trésorerie et les placements disponibles.","x":"Piège : ne pas y mettre les dettes fournisseurs, qui sont de l'exploitation. Depuis IFRS 16, les loyers capitalisés en font partie."},{"t":"af","q":"Qu'est-ce que le ratio de couverture des intérêts ?","r":"EBITDA ou résultat d'exploitation divisé par les charges d'intérêt.","x":"En dessous de 3, la marge de sécurité est mince. C'est un signal d'alerte avant même le gearing."},{"t":"af","q":"Qu'est-ce que le fonds de roulement ?","r":"Ressources stables moins emplois stables. Ce qui reste des financements longs après avoir payé les immobilisations.","x":"Il doit financer le BFR. Fonds de roulement inférieur au BFR signifie que la trésorerie est négative."},{"t":"af","q":"Quelle est la relation entre FR, BFR et trésorerie ?","r":"Trésorerie nette = fonds de roulement moins besoin en fonds de roulement.","x":"L'égalité fondamentale de l'analyse du bilan. Si on ne devait retenir qu'une formule, c'est celle-là."},{"t":"af","q":"Qu'est-ce que le BFR ?","r":"Stocks plus créances clients moins dettes fournisseurs, et plus généralement l'actif circulant d'exploitation moins le passif circulant d'exploitation.","x":"C'est de l'argent immobilisé dans le cycle. Le réduire libère du cash sans emprunter un euro."},{"t":"af","q":"Comment un BFR peut-il être négatif ?","r":"Quand les clients paient avant que les fournisseurs soient payés. C'est le cas de la grande distribution et de la restauration.","x":"Un BFR négatif est une ressource de financement gratuite. Il devient dangereux si l'activité chute brutalement."},{"t":"af","q":"Qu'est-ce que le DSO ?","r":"Days sales outstanding : le délai moyen de règlement client, en jours de chiffre d'affaires.","x":"Créances clients TTC divisées par le chiffre d'affaires TTC, multiplié par 365. Attention à ne pas mélanger HT et TTC."},{"t":"af","q":"Qu'est-ce que le DPO ?","r":"Days payables outstanding : le délai moyen de règlement fournisseur.","x":"L'allonger améliore la trésorerie mais dégrade la relation fournisseur, et la loi encadre les délais en France."},{"t":"af","q":"Qu'est-ce que le DIO ?","r":"Days inventory outstanding : le nombre de jours de stock.","x":"Le cycle de conversion du cash est DSO plus DIO moins DPO. C'est le nombre de jours pendant lesquels l'entreprise finance son cycle."},{"t":"af","q":"Quels sont les délais de paiement légaux en France ?","r":"En principe 60 jours à compter de la facture, ou 45 jours fin de mois si le contrat le prévoit.","x":"Le dépassement expose à une amende administrative, publiée. C'est devenu un vrai sujet de réputation."},{"t":"af","q":"Qu'est-ce que la capacité de remboursement ?","r":"Dette financière nette divisée par la CAF, exprimée en années.","x":"Repère bancaire courant : au-delà de 4 à 5 ans, le dossier devient difficile."},{"t":"af","q":"Qu'est-ce que le taux de rotation des stocks ?","r":"Coût des ventes divisé par le stock moyen. Il dit combien de fois le stock tourne dans l'année.","x":"Une rotation qui ralentit annonce souvent une dépréciation à venir. C'est un indicateur avancé de mauvaise nouvelle."},{"t":"af","q":"Qu'est-ce qu'un free cash flow ?","r":"Le cash généré par l'exploitation après impôt, moins les investissements et la variation du BFR.","x":"C'est ce qui reste vraiment disponible pour rembourser la dette et rémunérer l'actionnaire. Le chiffre roi de l'analyse."},{"t":"af","q":"Pourquoi le résultat net ne suffit-il pas ?","r":"Parce qu'il contient des écritures sans mouvement de trésorerie et ignore l'investissement et le BFR.","x":"La phrase à retenir : le résultat est une opinion, le cash est un fait."},{"t":"af","q":"Qu'est-ce que le tableau de flux de trésorerie ?","r":"Un état qui explique la variation de trésorerie en trois blocs : exploitation, investissement, financement.","x":"Le bon réflexe : un résultat qui monte avec un flux d'exploitation qui baisse doit toujours être expliqué."},{"t":"af","q":"Que signifie un flux d'exploitation négatif avec un résultat positif ?","r":"Le résultat n'est pas encaissé : le BFR gonfle, souvent par les créances ou les stocks.","x":"C'est le schéma typique d'une croissance mal financée. Beaucoup de défaillances arrivent en pleine croissance."},{"t":"af","q":"Qu'est-ce que l'EBITDA ?","r":"Earnings before interest, taxes, depreciation and amortization : le résultat avant intérêts, impôts et amortissements.","x":"Ce n'est pas du cash. Il ignore le BFR et l'investissement, deux postes qui peuvent tout absorber."},{"t":"af","q":"Qu'est-ce que l'EBIT ?","r":"Le résultat d'exploitation, après amortissements mais avant intérêts et impôts.","x":"EBITDA moins dotations aux amortissements égale EBIT. Savoir passer de l'un à l'autre en une phrase est attendu."},{"t":"af","q":"Qu'est-ce qu'un EBITDA ajusté et pourquoi s'en méfier ?","r":"Un EBITDA retraité d'éléments jugés non récurrents par la direction.","x":"Chaque entreprise a sa définition. Demandez toujours la liste des ajustements avant d'utiliser le chiffre."},{"t":"af","q":"Comment lit-on une évolution de chiffre d'affaires correctement ?","r":"En séparant l'effet volume, l'effet prix, l'effet périmètre et l'effet change.","x":"On parle alors de croissance organique, à périmètre et change constants. C'est le seul chiffre comparable d'une année sur l'autre."},{"t":"af","q":"Qu'est-ce que la croissance organique ?","r":"La croissance hors acquisitions, cessions et effets de change.","x":"Une croissance publiée à 12 pour cent dont 10 viennent d'une acquisition ne dit rien de la performance du métier."},{"t":"af","q":"Qu'est-ce qu'un effet de change et comment il se neutralise ?","r":"L'impact de la variation des devises sur les comptes consolidés. On le neutralise en recalculant l'année N aux cours de N moins 1.","x":"À taux de change constants, ou at constant currency. Formulation à connaître dans les communiqués."},{"t":"af","q":"Qu'est-ce que la saisonnalité et comment on la traite ?","r":"La répartition inégale de l'activité dans l'année. On compare toujours un mois au même mois de l'an dernier, pas au mois précédent.","x":"Ou on raisonne en cumul glissant sur douze mois, qui efface la saisonnalité par construction."},{"t":"af","q":"Qu'est-ce qu'un cumul glissant sur douze mois ?","r":"La somme des douze derniers mois, recalculée chaque mois.","x":"C'est l'outil le plus simple pour voir une tendance sans être trompé par la saison. À mettre dans tout tableau de bord."},{"t":"af","q":"Qu'est-ce qu'une analyse en tendance ?","r":"On regarde trois à cinq exercices pour distinguer un accident d'une dérive.","x":"Un seul exercice ne prouve rien. Trois points font une tendance, un point fait une anecdote."},{"t":"af","q":"Qu'est-ce qu'un benchmark sectoriel et où le trouver ?","r":"La comparaison aux concurrents. Sources : comptes déposés sur Pappers ou Infogreffe, communiqués, bases de la Banque de France.","x":"En entretien, dire où vous iriez chercher la donnée vaut autant que connaître le chiffre."},{"t":"af","q":"Qu'est-ce que la capacité d'autofinancement disponible ?","r":"La CAF moins les dividendes versés.","x":"C'est ce qui reste réellement dans l'entreprise pour investir et rembourser."},{"t":"af","q":"Qu'est-ce que le taux de distribution, ou payout ratio ?","r":"Dividendes divisés par le résultat net.","x":"Au-delà de 100 pour cent, l'entreprise distribue plus qu'elle ne gagne. Cela peut se justifier une année, pas trois."},{"t":"af","q":"Qu'est-ce qu'un covenant bancaire ?","r":"Un engagement chiffré pris envers la banque, souvent un ratio de levier ou de gearing testé chaque semestre.","x":"Le rompre déclenche l'exigibilité anticipée. C'est pour ça que le contrôle de gestion suit ces ratios tous les mois, pas tous les six mois."},{"t":"af","q":"Qu'est-ce que la trésorerie nette ?","r":"Disponibilités et placements moins les concours bancaires courants.","x":"Une trésorerie apparemment confortable financée par du découvert n'est pas une trésorerie. Toujours regarder le brut et le net."},{"t":"af","q":"Qu'est-ce que l'autonomie financière ?","r":"Capitaux propres divisés par le total du bilan.","x":"En dessous de 20 pour cent, la structure est fragile. Beaucoup de banques posent ce seuil comme un minimum."},{"t":"af","q":"Comment détecte-t-on un habillage de bilan ?","r":"On regarde les mouvements juste avant et juste après la clôture : cessions de créances, retard de paiement fournisseurs, factures anticipées.","x":"Un DSO qui plonge au 31 décembre et remonte en janvier est le signal le plus simple."},{"t":"af","q":"Qu'est-ce que l'affacturage et comment il change la lecture ?","r":"La cession de créances clients à un factor contre un paiement immédiat.","x":"Il réduit le DSO affiché sans améliorer la performance. Chercher l'information en annexe avant de conclure."},{"t":"af","q":"Qu'est-ce que la valeur d'entreprise ?","r":"Capitalisation boursière plus dette financière nette, plus intérêts minoritaires.","x":"Elle représente la valeur du métier, indépendamment de la façon dont il est financé. C'est le numérateur des multiples EV sur EBITDA."},{"t":"af","q":"Quelle différence entre valeur d'entreprise et valeur des capitaux propres ?","r":"La valeur des capitaux propres est la valeur d'entreprise moins la dette nette.","x":"Le passage de l'une à l'autre, appelé equity bridge, est une question de test très fréquente."},{"t":"af","q":"Qu'est-ce qu'un multiple d'EBITDA ?","r":"Valeur d'entreprise divisée par l'EBITDA. Il dit combien d'années d'EBITDA le marché paie.","x":"Comparer des multiples n'a de sens qu'entre sociétés du même secteur, de taille et de croissance proches."},{"t":"af","q":"Qu'est-ce que le PER ?","r":"Price earning ratio : cours de l'action divisé par le bénéfice par action.","x":"Un PER élevé veut dire que le marché attend de la croissance, pas que l'action est chère. Il n'a aucun sens si le résultat est négatif."},{"t":"af","q":"Qu'est-ce que le price to book ?","r":"Capitalisation divisée par les capitaux propres comptables.","x":"En dessous de 1, le marché valorise l'entreprise moins que ses fonds propres. Fréquent dans la banque, rare ailleurs sans raison."},{"t":"af","q":"Qu'est-ce qu'une analyse de rentabilité par client ?","r":"On affecte à chaque client sa marge et les coûts qu'il génère : logistique, service, retards de paiement.","x":"Le résultat surprend presque toujours. Une minorité de clients fait souvent la totalité de la marge."},{"t":"af","q":"Qu'est-ce que la loi de Pareto appliquée aux ventes ?","r":"Environ 20 pour cent des clients ou produits font 80 pour cent du résultat.","x":"À vérifier, pas à supposer. Le calculer prend dix minutes et change souvent la stratégie commerciale."},{"t":"af","q":"Qu'est-ce qu'un compte de résultat par nature et par destination ?","r":"Par nature : achats, personnel, amortissements. Par destination : coût des ventes, commercial, administratif, recherche.","x":"Les normes françaises privilégient la nature, l'anglo-saxon la destination. Savoir passer de l'un à l'autre est un vrai plus."},{"t":"af","q":"Qu'est-ce qu'un point mort en jours de chiffre d'affaires ?","r":"La date de l'année à laquelle l'entreprise a couvert ses charges fixes.","x":"Formulation qui parle beaucoup aux dirigeants : « cette année, vous êtes rentable à partir du 12 septembre »."},{"t":"af","q":"Qu'est-ce que la marge de sécurité ?","r":"La différence entre le chiffre d'affaires réalisé et le seuil de rentabilité, souvent exprimée en pourcentage.","x":"Elle dit de combien l'activité peut chuter avant de passer en perte. Un indicateur de risque très simple à produire."},{"t":"af","q":"Comment analyser une entreprise qui perd de l'argent mais grandit vite ?","r":"On regarde la marge brute unitaire, le coût d'acquisition client, et le temps de retour sur ce coût.","x":"Le vrai sujet est de savoir si l'unité économique est rentable. Si elle ne l'est pas, la croissance aggrave la perte."},{"t":"af","q":"Qu'est-ce que la LTV et le CAC ?","r":"Lifetime value : la marge totale d'un client sur sa durée de vie. CAC : coût d'acquisition d'un client.","x":"Repère du secteur : un ratio LTV sur CAC supérieur à 3 est considéré comme sain."},{"t":"af","q":"Qu'est-ce que le taux de churn ?","r":"La part de clients perdus sur une période.","x":"Sur un modèle d'abonnement, la durée de vie moyenne d'un client est environ 1 divisé par le taux de churn."},{"t":"cf","q":"Qu'est-ce que la valeur actuelle nette ?","r":"La somme des flux futurs actualisés, moins l'investissement initial.","x":"Règle de décision : VAN positive, on y va. C'est le seul critère qui intègre à la fois le temps et le risque."},{"t":"cf","q":"Pourquoi actualise-t-on les flux futurs ?","r":"Parce qu'un euro aujourd'hui vaut plus qu'un euro dans un an : il peut être placé et il est certain.","x":"Deux composantes dans le taux : la valeur du temps et la prime de risque."},{"t":"cf","q":"Qu'est-ce que le TRI ?","r":"Taux de rentabilité interne : le taux qui annule la VAN.","x":"Il se compare au coût du capital. Piège : le TRI suppose que les flux intermédiaires se replacent au même taux, ce qui est rarement vrai."},{"t":"cf","q":"Quelle est la limite du TRI face à la VAN ?","r":"Le TRI peut être multiple ou inexistant si les flux changent plusieurs fois de signe, et il favorise les petits projets.","x":"En cas de conflit entre TRI et VAN sur deux projets exclusifs, on suit la VAN."},{"t":"cf","q":"Qu'est-ce que le WACC ?","r":"Coût moyen pondéré du capital : le coût des fonds propres et de la dette, pondérés par leur poids dans le financement.","x":"Formule : Kcp x CP/(CP+D) + Kd x (1 - IS) x D/(CP+D). La dette est prise après impôt, car les intérêts sont déductibles."},{"t":"cf","q":"Comment estime-t-on le coût des fonds propres ?","r":"Par le MEDAF : taux sans risque plus bêta multiplié par la prime de risque du marché.","x":"En français MEDAF, en anglais CAPM. Savoir dire les deux."},{"t":"cf","q":"Qu'est-ce que le bêta d'une action ?","r":"Sa sensibilité aux mouvements du marché. Bêta 1, elle suit le marché. Bêta 1,5, elle amplifie de moitié.","x":"Le bêta mesure le risque systématique, celui qu'on ne peut pas diversifier. Le reste du risque est spécifique et s'efface dans un portefeuille."},{"t":"cf","q":"Qu'est-ce que le bêta désendetté ?","r":"Le bêta corrigé de l'effet de la dette, pour comparer des sociétés de structures financières différentes.","x":"On désendette les bêtas des comparables, on fait la moyenne, puis on réendette avec la structure cible. Question classique en test."},{"t":"cf","q":"Qu'est-ce que la prime de risque de marché ?","r":"Le surcroît de rendement attendu des actions par rapport au taux sans risque.","x":"Ordre de grandeur usuel en zone euro : entre 5 et 7 pour cent. Ne jamais donner un chiffre au centième, c'est une estimation."},{"t":"cf","q":"Qu'est-ce que la méthode DCF ?","r":"Discounted cash flow : on projette les flux disponibles, on les actualise au WACC, et on ajoute une valeur terminale.","x":"La valeur terminale pèse souvent 60 à 80 pour cent du total. C'est là qu'il faut être prudent, pas sur l'année 3."},{"t":"cf","q":"Comment calcule-t-on une valeur terminale ?","r":"Par la formule de Gordon Shapiro : flux de l'année suivante divisé par le WACC moins le taux de croissance perpétuelle.","x":"Le taux de croissance perpétuelle ne doit jamais dépasser la croissance de long terme de l'économie, autour de 2 pour cent."},{"t":"cf","q":"Qu'est-ce que la méthode des comparables ?","r":"On applique à l'entreprise les multiples observés sur des sociétés cotées similaires.","x":"Rapide et ancrée dans le marché, mais elle suppose que le marché a raison. À croiser toujours avec un DCF."},{"t":"cf","q":"Qu'est-ce que la méthode des transactions comparables ?","r":"On utilise les multiples payés lors d'opérations récentes sur le secteur.","x":"Ces multiples incluent une prime de contrôle. Ils sont donc supérieurs aux multiples boursiers, en général de 20 à 30 pour cent."},{"t":"cf","q":"Qu'est-ce que la méthode patrimoniale, ou actif net réévalué ?","r":"On réévalue chaque actif et chaque dette à sa valeur de marché.","x":"Pertinente pour l'immobilier et les holdings, inadaptée pour une société de services dont la valeur est dans les équipes."},{"t":"cf","q":"Pourquoi croise-t-on toujours plusieurs méthodes d'évaluation ?","r":"Parce qu'aucune n'est juste : on cherche une fourchette cohérente, pas un chiffre.","x":"Réponse à donner telle quelle en entretien. Un candidat qui annonce une valeur unique perd des points."},{"t":"cf","q":"Qu'est-ce qu'un goodwill ?","r":"L'écart entre le prix payé et la juste valeur des actifs nets acquis.","x":"Il représente ce qui n'est pas au bilan : marque, clients, savoir-faire. En IFRS il n'est pas amorti, il est testé chaque année."},{"t":"cf","q":"Qu'est-ce qu'une dépréciation de goodwill et ce qu'elle signale ?","r":"On constate que l'acquisition vaut moins que prévu. C'est une charge sans sortie de cash.","x":"Elle dit surtout que l'acquisition a été payée trop cher ou que le plan n'est pas tenu. Un signal de gouvernance."},{"t":"cf","q":"Qu'est-ce qu'une due diligence ?","r":"L'audit d'acquisition : financier, fiscal, juridique, social, parfois technique et environnemental.","x":"Son but n'est pas de dire oui ou non, mais de chiffrer les risques pour ajuster le prix ou obtenir des garanties."},{"t":"cf","q":"Qu'est-ce qu'une garantie d'actif et de passif ?","r":"Un engagement du vendeur d'indemniser l'acheteur si un passif apparaît après la vente sur des faits antérieurs.","x":"Elle est plafonnée, limitée dans le temps et souvent adossée à une garantie bancaire ou un séquestre."},{"t":"cf","q":"Qu'est-ce qu'un LBO ?","r":"Le rachat d'une société par endettement, la dette étant remboursée par les flux de la cible.","x":"Le moteur : l'effet de levier. Le risque : une cible cyclique ne supporte pas un levier élevé."},{"t":"cf","q":"Qu'est-ce que l'effet de levier financier ?","r":"L'endettement augmente la rentabilité des fonds propres tant que la rentabilité économique dépasse le coût de la dette.","x":"Le levier joue dans les deux sens. Si la rentabilité économique tombe sous le coût de la dette, il devient un effet de massue."},{"t":"cf","q":"Qu'est-ce qu'une augmentation de capital ?","r":"L'émission d'actions nouvelles contre apport d'argent ou de biens.","x":"Elle dilue les actionnaires existants s'ils ne suivent pas. Le droit préférentiel de souscription sert à les protéger."},{"t":"cf","q":"Qu'est-ce que la dilution ?","r":"La baisse du pourcentage détenu par un actionnaire après l'émission de titres nouveaux.","x":"On la mesure aussi sur le bénéfice par action. Une opération relutive augmente le BPA, une opération dilutive le réduit."},{"t":"cf","q":"Qu'est-ce qu'une obligation convertible ?","r":"Une obligation qui peut être échangée contre des actions selon une parité définie.","x":"L'émetteur paie un taux plus faible en échange de l'option de conversion. Très utilisé par les sociétés en croissance."},{"t":"cf","q":"Qu'est-ce que la dette mezzanine ?","r":"Une dette subordonnée, remboursée après la dette senior, plus chère et souvent assortie d'un accès au capital.","x":"Elle comble l'écart entre ce que la banque prête et ce que l'actionnaire apporte. Fréquente en LBO."},{"t":"cf","q":"Qu'est-ce que le capital risque et le capital développement ?","r":"Risque : financer une jeune société non rentable. Développement : financer la croissance d'une société établie.","x":"Le capital transmission, ou buyout, est le troisième métier. Savoir les distinguer est attendu en entretien de fonds."},{"t":"cf","q":"Qu'est-ce qu'une table de capitalisation ?","r":"Le tableau qui répartit le capital entre actionnaires, avec les instruments dilutifs.","x":"On la lit toujours en deux versions : non diluée et pleinement diluée."},{"t":"cf","q":"Qu'est-ce qu'un pacte d'actionnaires ?","r":"Un contrat entre actionnaires qui organise la gouvernance et les mouvements de titres.","x":"Clauses à connaître : préemption, agrément, sortie conjointe ou tag along, sortie forcée ou drag along."},{"t":"cf","q":"Qu'est-ce qu'une clause de liquidation préférentielle ?","r":"Elle garantit à un investisseur de récupérer sa mise en priorité lors d'une vente.","x":"Elle peut vider la part des fondateurs si la vente se fait à un prix modeste. Point central des négociations en capital risque."},{"t":"cf","q":"Qu'est-ce que le coût de la dette après impôt ?","r":"Le taux d'intérêt multiplié par un moins le taux d'impôt sur les sociétés.","x":"C'est l'économie d'impôt liée à la déductibilité des intérêts, appelée bouclier fiscal."},{"t":"cf","q":"Qu'est-ce que la structure financière optimale ?","r":"Le niveau de dette qui minimise le coût du capital, entre l'avantage fiscal et le coût de la détresse financière.","x":"Théorie du compromis, ou trade-off theory. À citer face à Modigliani et Miller, qui supposent un monde sans impôt ni faillite."},{"t":"cf","q":"Qu'est-ce que la théorie du financement hiérarchique ?","r":"Pecking order : on finance d'abord par l'autofinancement, puis par la dette, et en dernier par le capital.","x":"Explication : émettre des actions envoie un signal négatif au marché, celui que le titre est cher."},{"t":"cf","q":"Qu'est-ce qu'un plan de financement ?","r":"Un tableau pluriannuel qui confronte les besoins, investissements et BFR, aux ressources, CAF, emprunts, capital.","x":"C'est le document exigé par toute banque sur un dossier d'investissement. Il doit s'équilibrer chaque année, pas seulement au total."},{"t":"cf","q":"Qu'est-ce que le besoin de financement d'un projet ?","r":"L'investissement initial plus la variation de BFR qu'il génère.","x":"Oublier le BFR est l'erreur la plus fréquente sur un business plan de croissance."},{"t":"cf","q":"Qu'est-ce qu'un prêt amortissable et un prêt in fine ?","r":"Amortissable : on rembourse du capital à chaque échéance. In fine : on ne paie que les intérêts, le capital au terme.","x":"L'in fine soulage la trésorerie mais coûte plus cher au total et concentre le risque à l'échéance."},{"t":"cf","q":"Qu'est-ce qu'un différé d'amortissement ?","r":"Une période durant laquelle on ne rembourse pas le capital, en général au démarrage d'un projet.","x":"À demander systématiquement sur un investissement qui met du temps à produire du cash."},{"t":"cf","q":"Qu'est-ce qu'une caution et une garantie autonome ?","r":"La caution est accessoire au contrat principal. La garantie autonome est indépendante, elle se paie à première demande.","x":"La garantie autonome est bien plus dangereuse pour celui qui la donne, car il ne peut pas opposer les défenses du contrat."},{"t":"cf","q":"Qu'est-ce que le crédit-bail comme mode de financement ?","r":"Le loueur achète le bien et le loue avec option d'achat. Il finance à 100 pour cent sans apport.","x":"Plus cher qu'un emprunt, mais il préserve la capacité d'endettement bancaire et la garantie porte sur le bien."},{"t":"cf","q":"Qu'est-ce que l'affacturage inversé, ou reverse factoring ?","r":"Le donneur d'ordre met en place un financement qui permet à ses fournisseurs d'être payés plus tôt.","x":"Attention à la requalification en dette financière si le programme rallonge les délais de paiement du donneur d'ordre."},{"t":"cf","q":"Qu'est-ce qu'une introduction en bourse ?","r":"La mise sur le marché d'une partie du capital pour lever des fonds et donner de la liquidité aux actionnaires.","x":"Le coût réel dépasse les frais : transparence, coûts de conformité, pression sur le trimestre."},{"t":"cf","q":"Qu'est-ce qu'un rachat d'actions ?","r":"L'entreprise rachète ses propres titres, souvent pour les annuler.","x":"Cela augmente le bénéfice par action sans améliorer le métier. À regarder de près quand la direction est payée sur le BPA."},{"t":"cf","q":"Qu'est-ce que le fonds de commerce et comment il se valorise ?","r":"Clientèle, enseigne, droit au bail. Il se valorise souvent par un multiple du chiffre d'affaires ou de l'EBE selon le secteur.","x":"Les barèmes professionnels existent par métier. Ils donnent une fourchette d'entrée en négociation, pas une valeur."},{"t":"cf","q":"Qu'est-ce qu'une holding et à quoi elle sert ?","r":"Une société qui détient des participations. Elle permet de centraliser le contrôle, la trésorerie et parfois la dette d'acquisition.","x":"Le régime mère-fille et l'intégration fiscale sont ses deux principaux intérêts fiscaux."},{"t":"cf","q":"Qu'est-ce que le management package ?","r":"L'ensemble des instruments donnant aux dirigeants une part de la plus-value : actions gratuites, BSPCE, actions de préférence.","x":"Le sujet est autant fiscal que financier. La qualification en salaire ou en plus-value change tout."},{"t":"cf","q":"Qu'est-ce qu'un BSPCE ?","r":"Bon de souscription de parts de créateur d'entreprise : un droit d'acheter des actions à un prix fixé, réservé aux jeunes sociétés.","x":"C'est l'outil français d'intéressement des salariés de start-up. Conditions d'éligibilité strictes sur l'âge et la détention de la société."},{"t":"cf","q":"Qu'est-ce que la prime de contrôle ?","r":"Le surplus payé pour obtenir la majorité et diriger l'entreprise.","x":"Symétriquement, une décote de minorité et une décote d'illiquidité s'appliquent aux petites participations non cotées."},{"t":"cf","q":"Qu'est-ce qu'une décote d'illiquidité ?","r":"La réduction de valeur appliquée à un titre difficile à revendre.","x":"Ordre de grandeur retenu en pratique : de 10 à 30 pour cent selon la taille et la qualité de la société."},{"t":"tres","q":"Quelle est la différence entre résultat et trésorerie ?","r":"Le résultat mesure la performance, la trésorerie mesure les encaissements et décaissements réels.","x":"Une entreprise fait faillite par manque de trésorerie, jamais directement par manque de résultat."},{"t":"tres","q":"Qu'est-ce qu'un plan de trésorerie ?","r":"Un tableau des encaissements et décaissements prévus, en général semaine par semaine sur trois mois.","x":"La bonne maille dépend de la tension. En crise, on passe au quotidien sur treize semaines, c'est le standard des retournements."},{"t":"tres","q":"Qu'est-ce que la prévision à treize semaines ?","r":"Le format standard de prévision de trésorerie court terme, remis à jour chaque semaine.","x":"Treize semaines, c'est un trimestre. Assez long pour anticiper, assez court pour rester fiable."},{"t":"tres","q":"Qu'est-ce que le cash pooling ?","r":"La centralisation des trésoreries des filiales sur un compte pivot du groupe.","x":"Deux formes : notionnel, on fusionne seulement les intérêts, ou physique, l'argent bouge vraiment. La seconde crée des comptes courants intragroupe."},{"t":"tres","q":"Qu'est-ce qu'une convention de trésorerie ?","r":"Le contrat qui encadre les avances entre sociétés d'un même groupe.","x":"Indispensable : sans convention et sans intérêt de marché, l'administration peut y voir un acte anormal de gestion."},{"t":"tres","q":"Qu'est-ce que le découvert autorisé et la ligne de crédit confirmée ?","r":"Le découvert est révocable à tout moment. La ligne confirmée est engagée sur une durée, contre une commission.","x":"En période de tension, seule la ligne confirmée protège vraiment. C'est ce qu'il faut négocier quand tout va bien."},{"t":"tres","q":"Qu'est-ce que le Dailly ?","r":"La cession de créances professionnelles à une banque en garantie ou en escompte, par simple bordereau.","x":"Moins coûteux que l'affacturage mais sans garantie d'impayé ni gestion du recouvrement."},{"t":"tres","q":"Qu'est-ce que l'escompte commercial ?","r":"La banque avance le montant d'un effet de commerce avant son échéance, contre intérêts.","x":"À distinguer de l'escompte de règlement, qui est une remise accordée au client qui paie comptant."},{"t":"tres","q":"Qu'est-ce qu'un escompte de règlement et comment on le juge ?","r":"Une remise pour paiement anticipé. On la convertit en taux annuel pour la comparer au coût du financement.","x":"2 pour cent à 30 jours, c'est environ 24 pour cent par an. Presque toujours plus cher qu'un découvert."},{"t":"tres","q":"Qu'est-ce que la date de valeur ?","r":"La date à laquelle un mouvement porte intérêt, différente de la date d'opération.","x":"Quelques jours de valeur sur des flux importants coûtent cher. C'est un point de négociation bancaire classique."},{"t":"tres","q":"Qu'est-ce qu'une commission de mouvement ?","r":"Une commission bancaire assise sur le total des débits du compte.","x":"Souvent négociable jusqu'à zéro sur les gros flux. Beaucoup de PME la paient sans le savoir."},{"t":"tres","q":"Qu'est-ce que le float bancaire ?","r":"Le décalage entre le moment où l'argent quitte un compte et celui où il arrive sur l'autre.","x":"Il s'est beaucoup réduit avec les virements instantanés, mais il subsiste sur les chèques et l'international."},{"t":"tres","q":"Comment réduire le BFR sans dégrader le commerce ?","r":"Facturer plus vite, relancer avant l'échéance, supprimer les litiges de facturation, ajuster le stock aux ventes réelles.","x":"La relance préventive à J moins 5 est l'action la plus rentable et la moins agressive. Elle règle surtout les oublis."},{"t":"tres","q":"Qu'est-ce que le recouvrement amiable et le recouvrement contentieux ?","r":"Amiable : relances, échéanciers, négociation. Contentieux : mise en demeure, injonction de payer, action judiciaire.","x":"On ne passe au contentieux qu'après avoir tracé les relances. Sans preuve écrite, la procédure est fragile."},{"t":"tres","q":"Qu'est-ce qu'une balance âgée ?","r":"Le tableau des créances clients classées par ancienneté : à échoir, moins de 30 jours, 30 à 60, plus de 90.","x":"Au-delà de 90 jours, la probabilité de recouvrement chute fortement. C'est là qu'on déclenche l'escalade."},{"t":"tres","q":"Qu'est-ce qu'une assurance-crédit ?","r":"Une assurance qui couvre le risque d'impayé client, avec des encours garantis par client.","x":"Elle apporte aussi une information de solvabilité. Une réduction de garantie sur un client est un signal d'alerte à prendre au sérieux."},{"t":"tres","q":"Qu'est-ce que le risque de change et comment il se couvre ?","r":"Le risque qu'une variation de devise dégrade une créance ou une dette. On le couvre par des ventes à terme ou des options.","x":"La couverture naturelle vient en premier : facturer et acheter dans la même devise annule le risque sans coût."},{"t":"tres","q":"Qu'est-ce qu'un contrat de change à terme ?","r":"Un engagement d'échanger deux devises à une date future à un cours fixé aujourd'hui.","x":"Le cours à terme se déduit des taux d'intérêt des deux devises, pas d'une prévision. C'est une question de test fréquente."},{"t":"tres","q":"Qu'est-ce que le risque de taux pour une entreprise ?","r":"Le risque qu'une hausse des taux renchérisse la dette à taux variable.","x":"On le couvre par un swap, qui échange un taux variable contre un taux fixe, ou par un cap qui plafonne le taux."},{"t":"tres","q":"Qu'est-ce qu'un swap de taux ?","r":"Un échange de flux d'intérêt entre deux parties, en général fixe contre variable, sur un nominal qui ne s'échange pas.","x":"Seul le différentiel d'intérêt circule. C'est pour ça que le risque de contrepartie porte sur peu de chose."},{"t":"tres","q":"Qu'est-ce que le SEPA ?","r":"L'espace unique de paiement en euros : virements et prélèvements harmonisés dans la zone.","x":"Le mandat de prélèvement SEPA doit être conservé. Sans mandat valide, le débiteur peut contester pendant treize mois."},{"t":"tres","q":"Qu'est-ce qu'un virement instantané ?","r":"Un virement exécuté en moins de dix secondes, disponible 24 heures sur 24.","x":"Il est irrévocable. C'est ce qui en fait la cible privilégiée des fraudes au président et au faux fournisseur."},{"t":"tres","q":"Qu'est-ce que la fraude au changement de RIB ?","r":"Un faux fournisseur demande de modifier ses coordonnées bancaires et détourne le paiement.","x":"La parade est une procédure, pas un outil : double validation et rappel du fournisseur sur un numéro connu, jamais celui du mail."},{"t":"tres","q":"Qu'est-ce que la séparation des tâches en trésorerie ?","r":"Celui qui saisit un paiement n'est pas celui qui le valide.","x":"C'est le contrôle interne le plus efficace et le moins coûteux. Son absence est le premier constat des auditeurs en PME."},{"t":"tres","q":"Qu'est-ce qu'un budget de trésorerie annuel ?","r":"La traduction du budget en encaissements et décaissements, mois par mois, avec les décalages de règlement et la TVA.","x":"Un résultat prévisionnel positif peut donner une trésorerie négative six mois de l'année. Seul le budget de trésorerie le montre."},{"t":"tres","q":"Comment la TVA impacte-t-elle la trésorerie ?","r":"On encaisse la TVA des clients avant de la reverser, ce qui crée une avance de trésorerie, ou l'inverse en cas de crédit de TVA.","x":"Une entreprise en forte croissance d'investissement est souvent en crédit de TVA structurel. Demander le remboursement mensuel change tout."},{"t":"tres","q":"Qu'est-ce que le crédit de TVA et comment on le récupère ?","r":"Quand la TVA déductible dépasse la collectée. Remboursable sur demande, mensuellement si le régime le permet.","x":"Beaucoup d'entreprises le laissent en report par habitude. Le demander, c'est du cash immédiat."},{"t":"tres","q":"Qu'est-ce que le netting intragroupe ?","r":"La compensation des dettes et créances réciproques entre sociétés du groupe pour ne régler que le solde.","x":"Réduit les frais bancaires et le risque de change. Nécessite une convention et une date de netting fixe."},{"t":"tres","q":"Qu'est-ce qu'un covenant de trésorerie minimale ?","r":"Un engagement de conserver un niveau plancher de liquidités.","x":"Il se teste souvent à date fixe. Attention à ne pas piloter uniquement pour la date de test, l'auditeur le verra."},{"t":"tres","q":"Qu'est-ce que la position de trésorerie disponible ?","r":"Le solde bancaire plus les lignes non tirées, moins les paiements déjà engagés.","x":"C'est le seul chiffre qui compte en comité de crise. Le solde bancaire seul ne dit rien."},{"t":"tres","q":"Qu'est-ce qu'un stress test de trésorerie ?","r":"Une projection sous hypothèses dégradées : baisse d'activité, allongement des délais clients, perte d'une ligne bancaire.","x":"La bonne question n'est pas si on survit, mais combien de semaines on tient. On appelle ça le runway."},{"t":"tres","q":"Qu'est-ce que le runway ?","r":"Le nombre de mois de survie au rythme actuel de consommation de trésorerie.","x":"Trésorerie disponible divisée par la consommation mensuelle nette. Vocabulaire de start-up, mais utile partout."},{"t":"tres","q":"Qu'est-ce que le burn rate ?","r":"La consommation nette de trésorerie sur une période, en général mensuelle.","x":"Distinguer le burn brut, les dépenses, du burn net, dépenses moins encaissements. Les investisseurs parlent du net."},{"t":"tres","q":"Comment négocier avec sa banque en position de force ?","r":"En apportant des prévisions tenues dans le passé, un plan à jour et des demandes chiffrées, avant d'être en tension.","x":"La règle : on négocie une ligne quand on n'en a pas besoin. Demander en urgence, c'est accepter le prix imposé."},{"t":"conso","q":"À quoi sert la consolidation ?","r":"À présenter les comptes d'un groupe comme s'il s'agissait d'une seule entreprise.","x":"Sans elle, une holding qui détient dix sociétés n'a au bilan que des titres de participation. On ne voit ni le chiffre d'affaires ni la dette réelle."},{"t":"conso","q":"Quelles sont les trois méthodes de consolidation ?","r":"Intégration globale, mise en équivalence, et en normes françaises l'intégration proportionnelle.","x":"IFRS 11 a supprimé l'intégration proportionnelle pour les coentreprises, remplacée par la mise en équivalence."},{"t":"conso","q":"Quand applique-t-on l'intégration globale ?","r":"En cas de contrôle exclusif, en général au-delà de 50 pour cent des droits de vote.","x":"On intègre 100 pour cent des comptes, puis on isole la part des minoritaires au passif et au résultat."},{"t":"conso","q":"Quand applique-t-on la mise en équivalence ?","r":"En cas d'influence notable, présumée entre 20 et 50 pour cent.","x":"On ne reprend aucun poste de la filiale, seulement une ligne à l'actif et une ligne de quote-part de résultat."},{"t":"conso","q":"Qu'est-ce que le contrôle au sens d'IFRS 10 ?","r":"Le pouvoir sur l'entité, l'exposition à ses rendements variables, et la capacité d'influer sur ces rendements.","x":"Le contrôle peut exister sous 50 pour cent, par exemple avec un actionnariat très dispersé. C'est une analyse, pas un seuil."},{"t":"conso","q":"Qu'est-ce qu'un intérêt minoritaire ?","r":"La part des capitaux propres et du résultat d'une filiale qui revient aux actionnaires hors groupe.","x":"On dit aussi participation ne donnant pas le contrôle. Elle apparaît dans les capitaux propres consolidés, pas en dette."},{"t":"conso","q":"Qu'est-ce qu'une écriture d'élimination intragroupe ?","r":"On supprime les opérations internes : ventes, achats, créances, dettes, dividendes.","x":"Sinon le groupe se vendrait à lui-même et gonflerait son chiffre d'affaires. C'est le premier contrôle d'un consolideur."},{"t":"conso","q":"Qu'est-ce que l'élimination des résultats internes sur stocks ?","r":"On retire la marge interne encore incluse dans un stock détenu par une autre société du groupe.","x":"Tant que le bien n'est pas vendu à l'extérieur, le groupe n'a rien gagné. C'est un classique d'examen."},{"t":"conso","q":"Qu'est-ce que l'écart d'acquisition ?","r":"La différence entre le prix payé et la quote-part de situation nette réévaluée acquise.","x":"C'est le goodwill. En normes françaises il s'amortit, en IFRS il est seulement testé pour dépréciation."},{"t":"conso","q":"Qu'est-ce que l'écart d'évaluation ?","r":"La réévaluation des actifs et passifs identifiables de la cible à leur juste valeur à la date d'acquisition.","x":"Il se calcule AVANT le goodwill. Plus on identifie d'actifs, moins le goodwill est gros, et plus l'amortissement futur pèse."},{"t":"conso","q":"Qu'est-ce que la juste valeur ?","r":"Le prix qui serait reçu pour vendre un actif dans une transaction normale entre acteurs de marché.","x":"Trois niveaux de hiérarchie IFRS 13 : prix cotés, données observables, modèles internes. Le niveau 3 est le plus discutable."},{"t":"conso","q":"Qu'est-ce que le périmètre de consolidation ?","r":"La liste des sociétés incluses et la méthode retenue pour chacune.","x":"Toute entrée ou sortie de périmètre casse la comparabilité. C'est pour ça qu'on publie aussi une croissance à périmètre constant."},{"t":"conso","q":"Qu'est-ce qu'une liasse de consolidation ?","r":"Le jeu de données normé que chaque filiale remonte à la maison mère.","x":"Le travail du consolideur commence par la qualité de ces liasses. Un plan de comptes groupe unique évite 80 pour cent des problèmes."},{"t":"conso","q":"Comment convertit-on les comptes d'une filiale étrangère ?","r":"Bilan au cours de clôture, compte de résultat au cours moyen, capitaux propres au cours historique.","x":"L'écart va en écart de conversion dans les capitaux propres, pas en résultat. Question classique en entretien de consolidation."},{"t":"conso","q":"Qu'est-ce que l'écart de conversion ?","r":"L'écart né des différences de cours utilisés pour convertir une filiale étrangère.","x":"Il reste en capitaux propres tant que la filiale n'est pas cédée. À la cession, il est recyclé en résultat."},{"t":"conso","q":"Qu'est-ce que le résultat par action de base et dilué ?","r":"Base : résultat net part du groupe divisé par le nombre moyen d'actions. Dilué : en supposant l'exercice de tous les instruments dilutifs.","x":"L'écart entre les deux mesure la dilution potentielle. Un écart important mérite d'aller lire la note sur les instruments."},{"t":"conso","q":"Qu'est-ce que la norme IFRS 15 ?","r":"La reconnaissance du revenu, en cinq étapes, avec identification des obligations de performance.","x":"Elle a changé la date de comptabilisation dans les logiciels et les contrats de service. Retenir : on reconnaît quand le contrôle est transféré."},{"t":"conso","q":"Quelles sont les cinq étapes d'IFRS 15 ?","r":"Identifier le contrat, les obligations de performance, déterminer le prix, l'allouer, reconnaître le revenu.","x":"Les réciter dans l'ordre est un grand classique d'entretien en audit."},{"t":"conso","q":"Qu'est-ce que la norme IFRS 16 ?","r":"Les contrats de location entrent au bilan : un droit d'utilisation à l'actif, une dette de loyer au passif.","x":"Effet mécanique : l'EBITDA monte, la dette monte, le ratio de levier se dégrade. Toujours dire si un ratio est avant ou après IFRS 16."},{"t":"conso","q":"Qu'est-ce que la norme IFRS 9 ?","r":"Instruments financiers : classement, évaluation, et dépréciation par pertes de crédit attendues.","x":"Le changement majeur est le passage des pertes avérées aux pertes attendues. Cela avance dans le temps la reconnaissance du risque."},{"t":"conso","q":"Qu'est-ce que la norme IFRS 17 ?","r":"Les contrats d'assurance : évaluation des passifs par blocs de construction et marge de service contractuelle.","x":"Applicable depuis 2023. Elle rend enfin comparables les comptes des assureurs, ce qu'IFRS 4 ne faisait pas."},{"t":"conso","q":"Qu'est-ce que l'IAS 36 ?","r":"La dépréciation d'actifs : comparer la valeur comptable à la valeur recouvrable.","x":"Elle impose de tester le goodwill au moins une fois par an, et dès qu'un indice de perte apparaît."},{"t":"conso","q":"Qu'est-ce qu'une UGT ?","r":"Unité génératrice de trésorerie : le plus petit groupe d'actifs qui génère des flux indépendants.","x":"Le goodwill est affecté aux UGT, et le test se fait à ce niveau. Le découpage retenu change le résultat du test."},{"t":"conso","q":"Quelles sont les principales différences entre normes françaises et IFRS ?","r":"Locations, goodwill, résultat exceptionnel, juste valeur, reconnaissance du revenu, développement immobilisé.","x":"En citer trois avec l'effet chiffré suffit largement en entretien. Locations, goodwill et exceptionnel sont les plus parlantes."},{"t":"conso","q":"Qui doit appliquer les IFRS en France ?","r":"Les sociétés cotées sur un marché réglementé européen, pour leurs comptes consolidés.","x":"Les comptes sociaux restent en normes françaises. Une société peut donc publier deux résultats différents, et c'est normal."},{"t":"conso","q":"Qu'est-ce que le règlement ANC 2020-01 ?","r":"Le texte français qui régit les comptes consolidés en normes françaises.","x":"Il a remplacé le règlement 99-02. Le citer montre que vous connaissez le référentiel français, pas seulement les IFRS."},{"t":"conso","q":"Qu'est-ce qu'un impôt différé ?","r":"L'impôt correspondant aux différences temporelles entre le résultat comptable et le résultat fiscal.","x":"Actif si l'entreprise paiera moins plus tard, passif si elle paiera plus. Un impôt différé actif ne s'active que si le bénéfice futur est probable."},{"t":"conso","q":"Donnez un exemple d'impôt différé actif.","r":"Un déficit fiscal reportable, ou une provision non déductible immédiatement.","x":"C'est le poste le plus contesté par les auditeurs, parce qu'il repose sur des prévisions de bénéfices."},{"t":"conso","q":"Qu'est-ce que le taux effectif d'impôt ?","r":"La charge d'impôt totale divisée par le résultat avant impôt.","x":"L'écart avec le taux légal s'explique dans la preuve d'impôt. Un taux effectif très bas doit toujours être justifié."},{"t":"conso","q":"Qu'est-ce que la preuve d'impôt ?","r":"Le tableau qui réconcilie l'impôt théorique au taux légal et l'impôt réellement comptabilisé.","x":"Les lignes habituelles : différences permanentes, déficits non activés, taux étrangers, crédits d'impôt."},{"t":"conso","q":"Qu'est-ce qu'une différence permanente ?","r":"Une charge ou un produit qui ne sera jamais déductible ou jamais imposable.","x":"Exemples : amendes, une partie des cadeaux, la taxe sur les véhicules. Elles ne génèrent aucun impôt différé."},{"t":"conso","q":"Qu'est-ce que la mise en équivalence négative ?","r":"Quand la quote-part de pertes dépasse la valeur des titres, la participation est ramenée à zéro.","x":"On ne va sous zéro que si le groupe a une obligation de couvrir les pertes. Sinon on arrête à zéro."},{"t":"conso","q":"Qu'est-ce qu'une variation de pourcentage d'intérêt sans perte de contrôle ?","r":"Un rachat de minoritaires. En IFRS, l'écart va directement en capitaux propres, sans goodwill nouveau.","x":"C'est une transaction entre actionnaires, donc elle ne passe pas par le résultat. Piège fréquent."},{"t":"conso","q":"Que se passe-t-il en cas de perte de contrôle d'une filiale ?","r":"On déconsolide, on réévalue la participation conservée à sa juste valeur, et l'écart passe en résultat.","x":"Ce résultat de déconsolidation peut être très gros et n'a rien d'opérationnel. À isoler dans toute analyse."},{"t":"conso","q":"Qu'est-ce que le tableau de variation des capitaux propres ?","r":"Un état obligatoire qui explique le passage des capitaux propres d'ouverture à ceux de clôture.","x":"Il révèle les mouvements qui ne passent pas par le résultat : écarts de conversion, réévaluations, opérations sur minoritaires."},{"t":"conso","q":"Qu'est-ce que le résultat global, ou OCI ?","r":"Other comprehensive income : le résultat net plus les éléments comptabilisés directement en capitaux propres.","x":"Écarts actuariels, couvertures de flux, écarts de conversion. Certains seront recyclés en résultat, d'autres jamais."},{"t":"conso","q":"Qu'est-ce qu'un engagement de retraite et comment il se comptabilise ?","r":"IAS 19 : les régimes à prestations définies sont provisionnés selon des hypothèses actuarielles.","x":"Les écarts actuariels vont en OCI et ne sont jamais recyclés. Le taux d'actualisation retenu change beaucoup le montant."},{"t":"conso","q":"Qu'est-ce qu'un régime à cotisations définies ?","r":"L'employeur verse une cotisation et n'a aucune obligation au-delà.","x":"Aucune provision au bilan, seulement une charge. C'est le régime général français pour la retraite de base."},{"t":"conso","q":"Qu'est-ce que l'information sectorielle ?","r":"IFRS 8 : la présentation des résultats par secteur d'activité tel que le suit la direction.","x":"C'est l'approche du management. Elle permet de vérifier que la communication externe correspond au pilotage interne."},{"t":"conso","q":"Qu'est-ce que la CSRD ?","r":"La directive européenne de reporting de durabilité, qui impose des informations extra-financières auditées.","x":"Elle s'appuie sur les normes ESRS et le principe de double matérialité : impact de l'entreprise sur le monde, et du monde sur l'entreprise."},{"t":"conso","q":"Qu'est-ce que la double matérialité ?","r":"Analyser à la fois l'impact de l'entreprise sur l'environnement et la société, et les risques que ces sujets font peser sur l'entreprise.","x":"C'est la spécificité européenne. Le référentiel américain ne retient que la matérialité financière."},{"t":"conso","q":"Qu'est-ce que la taxonomie européenne ?","r":"Une classification des activités économiques considérées comme durables, avec des critères techniques.","x":"Les entreprises publient la part de leur chiffre d'affaires, de leurs CAPEX et OPEX alignés. C'est devenu un indicateur suivi par les investisseurs."},{"t":"fisc","q":"Quel est le taux normal de l'impôt sur les sociétés en France ?","r":"25 pour cent, avec un taux réduit de 15 pour cent sur les premiers 42 500 euros de bénéfice pour les PME éligibles.","x":"Conditions du taux réduit : chiffre d'affaires sous 10 millions et capital entièrement libéré détenu à 75 pour cent par des personnes physiques."},{"t":"fisc","q":"Comment passe-t-on du résultat comptable au résultat fiscal ?","r":"On ajoute les charges non déductibles et on retranche les produits non imposables.","x":"C'est le tableau 2058-A de la liasse. Savoir citer trois réintégrations classiques est attendu : amendes, part des véhicules, provisions non déductibles."},{"t":"fisc","q":"Citez trois charges non déductibles.","r":"Amendes et pénalités, la fraction non déductible des amortissements de véhicules de tourisme, certaines provisions et les dépenses somptuaires.","x":"La taxe sur les véhicules de société et l'IS lui-même ne sont pas déductibles non plus."},{"t":"fisc","q":"Qu'est-ce qu'un déficit reportable en avant ?","r":"Un déficit imputable sur les bénéfices futurs, sans limite de durée, mais plafonné chaque année.","x":"Plafond : 1 million d'euros plus 50 pour cent de la fraction du bénéfice au-delà. Le connaître fait la différence."},{"t":"fisc","q":"Qu'est-ce que le carry-back ?","r":"Le report en arrière du déficit sur le bénéfice de l'exercice précédent, générant une créance sur le Trésor.","x":"Limité à 1 million d'euros et à un seul exercice. La créance est remboursable au bout de cinq ans, ou mobilisable auprès d'une banque."},{"t":"fisc","q":"Qu'est-ce que le régime mère-fille ?","r":"Les dividendes reçus d'une filiale détenue à au moins 5 pour cent sont exonérés, hors quote-part de frais de 5 pour cent.","x":"Il faut conserver les titres deux ans. L'imposition réelle est donc de 5 pour cent du dividende au taux de l'IS, soit 1,25 pour cent."},{"t":"fisc","q":"Qu'est-ce que l'intégration fiscale ?","r":"Un régime où la mère paie l'IS sur la somme des résultats du groupe, en compensant bénéfices et déficits.","x":"Détention à 95 pour cent au moins. Le gain principal est la compensation immédiate des pertes d'une filiale."},{"t":"fisc","q":"Qu'est-ce que la CVAE et où elle en est ?","r":"Cotisation sur la valeur ajoutée des entreprises, en cours de suppression progressive.","x":"Le calendrier a été décalé plusieurs fois par les lois de finances successives. Toujours vérifier l'année en cours avant d'affirmer un taux."},{"t":"fisc","q":"Qu'est-ce que la CFE ?","r":"Cotisation foncière des entreprises, assise sur la valeur locative des locaux utilisés.","x":"Avec la CVAE, elle forme la contribution économique territoriale, qui a remplacé la taxe professionnelle en 2010."},{"t":"fisc","q":"Qu'est-ce que le CIR ?","r":"Crédit d'impôt recherche : 30 pour cent des dépenses de recherche éligibles jusqu'à 100 millions d'euros.","x":"Le dossier justificatif technique compte autant que le calcul. Sans description scientifique des travaux, le contrôle se passe mal."},{"t":"fisc","q":"Qu'est-ce que le CII ?","r":"Crédit d'impôt innovation, réservé aux PME, sur les dépenses de prototypes et d'installations pilotes de produits nouveaux.","x":"Le taux et le plafond ont bougé récemment. Il se déclare sur le même formulaire 2069-A-SD que le CIR."},{"t":"fisc","q":"Comment se déclare un CIR ou un CII ?","r":"Formulaire 2069-A-SD, transmis par voie électronique avec la liasse.","x":"L'EDI est la seule voie possible pour les entreprises à l'IS. Une déclaration papier est irrecevable."},{"t":"fisc","q":"Qu'est-ce que la TVA sur les débits et sur les encaissements ?","r":"Sur les biens, la TVA est due à la livraison. Sur les services, à l'encaissement, sauf option pour les débits.","x":"L'option pour les débits fait payer la TVA plus tôt mais simplifie le suivi. Elle doit figurer sur les factures."},{"t":"fisc","q":"Quels sont les taux de TVA en France ?","r":"20 pour cent normal, 10 pour cent intermédiaire, 5,5 pour cent réduit, 2,1 pour cent particulier.","x":"5,5 sur l'alimentaire et les livres, 10 sur la restauration et les travaux, 2,1 sur les médicaments remboursables et la presse."},{"t":"fisc","q":"La TVA sur les frais de restaurant est-elle déductible ?","r":"Oui, si la dépense est professionnelle et la facture au nom de l'entreprise.","x":"Attention aux autres cas : essence des voitures particulières déductible à 80 pour cent, et rien sur les frais kilométriques."},{"t":"fisc","q":"La TVA sur les frais kilométriques est-elle récupérable ?","r":"Non. L'indemnité kilométrique n'est pas une facture, il n'y a aucune TVA à déduire.","x":"Erreur très fréquente en note de frais. Elle se voit tout de suite dans un contrôle."},{"t":"fisc","q":"Qu'est-ce qu'une déclaration CA3 ?","r":"La déclaration mensuelle ou trimestrielle de TVA au régime réel normal.","x":"La CA12 est la déclaration annuelle du régime simplifié. Savoir laquelle s'applique selon le chiffre d'affaires est basique mais testé."},{"t":"fisc","q":"Qu'est-ce que la DEB et la DES ?","r":"Déclarations d'échanges de biens et de services entre États membres, aujourd'hui remplacées côté biens par l'enquête statistique et l'état récapitulatif.","x":"Les seuils et les formats ont changé en 2022. Vérifier l'obligation en cours avant de conseiller."},{"t":"fisc","q":"Qu'est-ce que le prix de transfert ?","r":"Le prix des transactions entre sociétés d'un même groupe situées dans des pays différents.","x":"Il doit respecter le principe de pleine concurrence. Une documentation est obligatoire au-delà de certains seuils de chiffre d'affaires."},{"t":"fisc","q":"Qu'est-ce que la facturation électronique obligatoire ?","r":"La réforme qui impose l'émission et la réception de factures au format électronique entre entreprises françaises.","x":"Le calendrier a été reporté plusieurs fois. Toujours vérifier la date en vigueur avant de la citer en entretien."},{"t":"fisc","q":"Qu'est-ce que le e-reporting dans cette réforme ?","r":"La transmission à l'administration des données de transactions non couvertes par la facturation électronique, comme les ventes aux particuliers.","x":"Deux volets distincts : e-invoicing entre entreprises françaises, e-reporting pour le reste."},{"t":"fisc","q":"Qu'est-ce que la taxe sur les salaires ?","r":"Une taxe due par les employeurs non soumis à la TVA sur au moins 90 pour cent de leur chiffre d'affaires.","x":"Elle frappe surtout les banques, assurances, associations et professions médicales. Barème progressif par tranches de salaire."},{"t":"fisc","q":"Qu'est-ce que le forfait social ?","r":"Une contribution patronale sur certaines rémunérations exonérées de cotisations, comme l'intéressement.","x":"Il a été supprimé pour l'intéressement dans les entreprises de moins de 250 salariés. Un point à connaître en PME."},{"t":"fisc","q":"Qu'est-ce que la participation et l'intéressement ?","r":"La participation est obligatoire au-delà de 50 salariés et redistribue une part du bénéfice. L'intéressement est facultatif et lié à des objectifs.","x":"Les deux sont exonérées de cotisations salariales et bénéficient d'un régime fiscal favorable si elles sont bloquées."},{"t":"fisc","q":"Qu'est-ce qu'un acompte d'IS ?","r":"Un versement anticipé de l'impôt, en principe quatre acomptes calculés sur le résultat de l'exercice précédent.","x":"Dates repères : 15 mars, 15 juin, 15 septembre, 15 décembre. Le solde se règle au 15 mai pour un exercice clos au 31 décembre."},{"t":"fisc","q":"Qu'est-ce qu'un contrôle fiscal et quelle est la prescription ?","r":"La vérification par l'administration. En principe trois ans en matière d'IS et de TVA.","x":"Le délai se compte à partir de la fin de l'année d'imposition. Il est allongé en cas d'activité occulte."},{"t":"fisc","q":"Qu'est-ce qu'un acte anormal de gestion ?","r":"Une opération contraire à l'intérêt de l'entreprise, comme une avance sans intérêt à une société liée.","x":"L'administration réintègre l'avantage consenti. C'est le fondement du redressement sur les conventions intragroupe mal formalisées."},{"t":"fisc","q":"Qu'est-ce que l'abus de droit fiscal ?","r":"Un montage à but exclusivement, ou principalement, fiscal.","x":"Depuis 2019, le critère principalement fiscal existe à côté du critère exclusivement fiscal. Il élargit beaucoup le champ."},{"t":"fisc","q":"Qu'est-ce que le rescrit fiscal ?","r":"Une prise de position formelle de l'administration sur une situation donnée, qui l'engage.","x":"C'est l'outil de sécurisation le plus efficace sur un montage complexe. Peu utilisé en PME, à tort."},{"t":"fisc","q":"Qu'est-ce que le pilier 2 de l'OCDE ?","r":"Un impôt minimum mondial de 15 pour cent sur les bénéfices des grands groupes.","x":"Applicable aux groupes au-delà de 750 millions d'euros de chiffre d'affaires. Transposé en droit français."},{"t":"fisc","q":"Qu'est-ce que la retenue à la source sur dividendes ?","r":"Un prélèvement opéré par l'État de source lors du versement à un non-résident.","x":"Les conventions fiscales bilatérales en réduisent le taux. Le régime mère-fille européen peut l'annuler totalement."},{"t":"fisc","q":"Qu'est-ce qu'une convention fiscale internationale ?","r":"Un traité entre deux États qui répartit le droit d'imposer et évite la double imposition.","x":"La France en a signé plus de cent vingt. Toujours vérifier la convention applicable avant de conclure sur une retenue à la source."},{"t":"fisc","q":"Qu'est-ce que la TVA intracommunautaire sur les acquisitions ?","r":"L'acheteur autoliquide : il collecte et déduit la même TVA.","x":"Le numéro de TVA du client doit être vérifié dans la base VIES. Un numéro invalide fait tomber l'exonération côté vendeur."},{"t":"fisc","q":"Qu'est-ce que le régime des plus-values de cession de titres de participation ?","r":"Exonération sous réserve d'une quote-part de frais et charges de 12 pour cent du montant brut de la plus-value.","x":"Régime dit du long terme, si les titres sont détenus depuis au moins deux ans. Un des piliers de la fiscalité des holdings."},{"t":"mkt","q":"Qu'est-ce qu'une obligation ?","r":"Un titre de créance : l'émetteur emprunte, verse des coupons et rembourse le nominal à l'échéance.","x":"L'obligataire est créancier, l'actionnaire est propriétaire. Le premier passe avant le second en cas de faillite."},{"t":"mkt","q":"Pourquoi le prix d'une obligation baisse quand les taux montent ?","r":"Parce qu'un titre à ancien coupon devient moins attractif qu'une émission neuve mieux rémunérée. Son prix s'ajuste à la baisse.","x":"Relation inverse, à retenir absolument. C'est la base de tout raisonnement obligataire."},{"t":"mkt","q":"Qu'est-ce que la duration d'une obligation ?","r":"La durée de vie moyenne pondérée des flux, et par extension la sensibilité du prix à une variation de taux.","x":"Duration 5 signifie qu'un point de hausse des taux fait perdre environ 5 pour cent de valeur. Approximation valable pour de petits mouvements."},{"t":"mkt","q":"Qu'est-ce que la convexité ?","r":"La courbure de la relation prix-taux, que la duration seule ne capte pas.","x":"Elle rend la duration fausse sur de gros mouvements. Une convexité positive est favorable au porteur."},{"t":"mkt","q":"Qu'est-ce qu'un coupon et un rendement actuariel ?","r":"Le coupon est l'intérêt versé. Le rendement actuariel est le taux qui égalise le prix payé et les flux futurs.","x":"Une obligation achetée sous le pair a un rendement supérieur à son coupon. C'est ce que regarde l'investisseur, pas le coupon."},{"t":"mkt","q":"Qu'est-ce que le spread de crédit ?","r":"L'écart de rendement entre une obligation d'entreprise et une obligation d'État de même maturité.","x":"Il rémunère le risque de défaut et le risque de liquidité. Il s'écarte violemment en période de stress."},{"t":"mkt","q":"Qu'est-ce que le spread OAT-Bund ?","r":"L'écart entre le taux de l'emprunt d'État français et l'allemand à 10 ans.","x":"C'est le thermomètre du risque politique et budgétaire français. Un chiffre suivi quotidiennement par le marché."},{"t":"mkt","q":"Qu'est-ce que la courbe des taux ?","r":"La représentation des taux d'intérêt selon la maturité.","x":"Normalement croissante. Une courbe inversée, court terme au-dessus du long terme, a souvent précédé les récessions."},{"t":"mkt","q":"Qu'est-ce qu'une notation de crédit ?","r":"Un avis d'agence sur la capacité d'un émetteur à rembourser, de AAA à D.","x":"Investment grade jusqu'à BBB moins, high yield en dessous. Cette frontière déclenche des ventes forcées chez beaucoup d'investisseurs."},{"t":"mkt","q":"Qu'est-ce qu'un ange déchu, ou fallen angel ?","r":"Un émetteur qui passe d'investment grade à high yield.","x":"Le passage force des ventes chez les fonds contraints. C'est pour cela que le spread s'écarte avant même la dégradation."},{"t":"mkt","q":"Qu'est-ce qu'une action ?","r":"Un titre de propriété qui donne droit au dividende et au vote.","x":"L'actionnaire est créancier résiduel : il touche après tout le monde, ce qui explique son rendement attendu plus élevé."},{"t":"mkt","q":"Qu'est-ce que le dividende et le détachement ?","r":"La part de résultat distribuée. Au détachement, le cours baisse mécaniquement du montant du dividende.","x":"Croire qu'on gagne de l'argent en achetant juste avant le détachement est une erreur de débutant."},{"t":"mkt","q":"Qu'est-ce que la volatilité ?","r":"L'ampleur des variations d'un actif, mesurée par l'écart type des rendements.","x":"Elle mesure le risque, pas la perte. Un actif peut être volatil et très rentable sur la durée."},{"t":"mkt","q":"Qu'est-ce que la VaR ?","r":"Valeur en risque : la perte qui ne sera pas dépassée avec une probabilité donnée, sur un horizon donné.","x":"Elle ne dit rien de ce qui se passe au-delà du seuil. C'est sa limite principale."},{"t":"mkt","q":"Qu'est-ce que la TVaR, ou expected shortfall ?","r":"La perte moyenne au-delà du seuil de VaR.","x":"Elle répond justement à la limite de la VaR. Bâle III l'a retenue à la place de la VaR pour le risque de marché."},{"t":"mkt","q":"Qu'est-ce que la diversification ?","r":"Répartir le risque sur des actifs peu corrélés pour réduire le risque total sans réduire le rendement attendu.","x":"Elle n'élimine que le risque spécifique. Le risque de marché, lui, ne se diversifie pas."},{"t":"mkt","q":"Qu'est-ce que la corrélation et pourquoi elle trahit en crise ?","r":"La mesure du lien entre deux actifs. En crise, presque tout devient corrélé à 1.","x":"C'est le grand piège des modèles de risque : la diversification disparaît au moment précis où on en a besoin."},{"t":"mkt","q":"Qu'est-ce que le ratio de Sharpe ?","r":"Le rendement au-delà du taux sans risque, divisé par la volatilité.","x":"Il mesure le rendement par unité de risque. Au-dessus de 1, c'est considéré comme bon."},{"t":"mkt","q":"Qu'est-ce que l'alpha et le bêta d'un gérant ?","r":"Le bêta est l'exposition au marché, l'alpha est la performance en plus, attribuée au talent.","x":"Beaucoup d'alpha apparent n'est que du bêta caché sur un facteur non identifié. C'est le débat central de la gestion active."},{"t":"mkt","q":"Qu'est-ce que la tracking error ?","r":"L'écart type de la différence de performance entre un portefeuille et son indice.","x":"Faible pour un fonds indiciel, élevée pour une gestion de conviction. C'est une contrainte, pas une qualité."},{"t":"mkt","q":"Qu'est-ce qu'un ETF ?","r":"Un fonds indiciel coté en bourse, qui réplique un indice à frais réduits.","x":"Deux modes de réplication : physique, il détient les titres, ou synthétique, il passe par un swap. Le second ajoute un risque de contrepartie."},{"t":"mkt","q":"Qu'est-ce qu'un OPCVM ?","r":"Un organisme de placement collectif en valeurs mobilières : SICAV ou fonds commun de placement.","x":"En droit européen, la directive UCITS encadre ceux qui peuvent être vendus au grand public dans toute l'Union."},{"t":"mkt","q":"Qu'est-ce que la valeur liquidative ?","r":"La valeur d'une part de fonds : actif net divisé par le nombre de parts.","x":"Elle se calcule à une fréquence définie dans le prospectus. Un fonds immobilier peut n'en publier qu'une par mois."},{"t":"mkt","q":"Qu'est-ce qu'un produit dérivé ?","r":"Un contrat dont la valeur dépend d'un sous-jacent : action, taux, devise, matière première.","x":"Il sert à couvrir ou à spéculer. C'est le même instrument, seule l'intention change."},{"t":"mkt","q":"Qu'est-ce qu'un contrat à terme ?","r":"Un engagement ferme d'acheter ou vendre à une date future à un prix fixé.","x":"Futures standardisés sur marché organisé, forwards sur mesure de gré à gré. La différence porte sur la liquidité et le risque de contrepartie."},{"t":"mkt","q":"Qu'est-ce qu'une option call et une option put ?","r":"Le call donne le droit d'acheter, le put le droit de vendre, à un prix d'exercice.","x":"Droit et non obligation, c'est toute la différence avec un future. L'acheteur paie une prime pour ce droit."},{"t":"mkt","q":"Qu'est-ce que la valeur intrinsèque et la valeur temps d'une option ?","r":"Intrinsèque : le gain si on exerçait maintenant. Temps : ce qu'on paie pour la possibilité que ça s'améliore.","x":"La valeur temps s'érode jusqu'à zéro à l'échéance. C'est le theta."},{"t":"mkt","q":"Que mesurent le delta et le vega d'une option ?","r":"Delta : sensibilité au prix du sous-jacent. Vega : sensibilité à la volatilité.","x":"Les grecques de base à citer : delta, gamma, theta, vega, rho. En connaître trois avec leur sens suffit en entretien corporate."},{"t":"mkt","q":"Qu'est-ce qu'un swap de devises ?","r":"L'échange de flux dans deux devises différentes, capital souvent inclus.","x":"Utilisé pour financer une filiale étrangère sans risque de change. À distinguer du swap de taux, où le nominal ne s'échange pas."},{"t":"mkt","q":"Qu'est-ce qu'un CDS ?","r":"Credit default swap : une assurance contre le défaut d'un émetteur, contre prime périodique.","x":"Son prix est lu comme une probabilité de défaut implicite. C'est un indicateur avancé du stress sur un émetteur."},{"t":"mkt","q":"Qu'est-ce que le marché primaire et le marché secondaire ?","r":"Primaire : émission de titres neufs, l'argent va à l'émetteur. Secondaire : échange entre investisseurs.","x":"L'entreprise ne reçoit rien sur le secondaire. Elle y a pourtant tout intérêt : la liquidité fait baisser son coût d'émission."},{"t":"mkt","q":"Qu'est-ce que la liquidité d'un marché ?","r":"La capacité d'acheter ou vendre vite, en volume, sans faire bouger le prix.","x":"Elle se mesure par la fourchette achat-vente et la profondeur du carnet. Elle disparaît exactement quand on en a besoin."},{"t":"mkt","q":"Qu'est-ce que le spread bid-ask ?","r":"L'écart entre le prix acheteur et le prix vendeur.","x":"C'est le coût implicite de la transaction. Sur des titres peu liquides, il coûte plus cher que les frais de courtage."},{"t":"mkt","q":"Qu'est-ce qu'un indice boursier ?","r":"Un panier représentatif de titres, en général pondéré par la capitalisation flottante.","x":"Le CAC 40 est un indice de prix pour la version usuelle, le CAC 40 GR intègre les dividendes réinvestis. L'écart est énorme sur dix ans."},{"t":"mkt","q":"Qu'est-ce que le flottant ?","r":"La part du capital réellement disponible à l'échange sur le marché.","x":"Une société peut être grosse et peu liquide si son flottant est faible. Cela affecte son entrée dans les indices."},{"t":"mkt","q":"Qu'est-ce que la capitalisation boursière ?","r":"Le nombre d'actions multiplié par le cours.","x":"Ce n'est pas la valeur de l'entreprise : il faut y ajouter la dette nette pour obtenir la valeur d'entreprise."},{"t":"mkt","q":"Qu'est-ce qu'un OPA et une OPE ?","r":"Offre publique d'achat, payée en numéraire. Offre publique d'échange, payée en titres.","x":"L'OPE dilue l'acquéreur mais préserve sa trésorerie. Le choix envoie un signal sur la valorisation de son propre titre."},{"t":"mkt","q":"Qu'est-ce qu'un franchissement de seuil ?","r":"L'obligation de déclarer quand on dépasse certains pourcentages du capital ou des droits de vote.","x":"Premier seuil à 5 pour cent en France. Au-delà de 30 pour cent, l'offre publique devient obligatoire."},{"t":"mkt","q":"Qu'est-ce que le taux sans risque ?","r":"Le rendement d'un actif considéré comme sûr, en pratique une obligation d'État de la zone monétaire.","x":"En zone euro, on prend souvent le Bund allemand. Depuis les crises souveraines, le mot sans risque est à manier avec prudence."},{"t":"mkt","q":"Qu'est-ce que l'Euribor et l'ESTER ?","r":"Euribor : taux interbancaire à terme de la zone euro. ESTER, ou euro short-term rate : taux au jour le jour calculé sur transactions réelles.","x":"L'ESTER a remplacé l'EONIA. La réforme des indices vient des manipulations du LIBOR."},{"t":"mkt","q":"Qu'est-ce qu'un taux directeur ?","r":"Le taux auquel la banque centrale prête aux banques commerciales.","x":"En zone euro, le taux de dépôt est devenu le taux pivot du marché monétaire, plus que le taux de refinancement."},{"t":"mkt","q":"Qu'est-ce que le quantitative easing ?","r":"L'achat massif de titres par la banque centrale pour faire baisser les taux longs et injecter de la liquidité.","x":"Le mouvement inverse, la réduction du bilan, s'appelle quantitative tightening."},{"t":"mkt","q":"Qu'est-ce qu'une obligation indexée sur l'inflation ?","r":"Une obligation dont le nominal ou le coupon suit un indice des prix.","x":"En France, les OATi suivent l'inflation française et les OAT€i l'inflation de la zone euro. Utiles pour un passif indexé."},{"t":"mkt","q":"Qu'est-ce que le point mort d'inflation, ou breakeven ?","r":"L'écart de rendement entre une obligation nominale et une obligation indexée de même maturité.","x":"Il donne l'inflation anticipée par le marché. Un indicateur suivi de près par les banques centrales."},{"t":"mkt","q":"Qu'est-ce qu'un fonds monétaire ?","r":"Un fonds investi en titres de créance très courts, servant de placement de trésorerie.","x":"Il n'est pas garanti. En 2008 certains fonds monétaires dits dynamiques ont perdu de la valeur, ce que personne n'attendait."},{"t":"mkt","q":"Qu'est-ce que le private equity par rapport à la bourse ?","r":"L'investissement en capital dans des sociétés non cotées, avec un horizon de cinq à sept ans.","x":"Moins liquide, valorisé moins souvent, ce qui lisse artificiellement la volatilité affichée. On parle de lissage de valorisation."},{"t":"mkt","q":"Qu'est-ce que la dette privée ?","r":"Des prêts consentis directement aux entreprises par des fonds, sans passer par les banques ni le marché obligataire.","x":"Classe d'actifs qui a beaucoup grossi depuis le durcissement des règles bancaires. Le régulateur en surveille les risques."},{"t":"mkt","q":"Qu'est-ce que l'ISR et l'article 8 SFDR ?","r":"Investissement socialement responsable. L'article 8 désigne un fonds qui promeut des caractéristiques environnementales ou sociales.","x":"L'article 9 vise un objectif d'investissement durable. La distinction est devenue un argument commercial majeur."},{"t":"mkt","q":"Qu'est-ce que le greenwashing et comment il se repère ?","r":"Présenter comme durable un produit qui ne l'est pas. On le repère en comparant les engagements affichés au portefeuille réel.","x":"Les régulateurs européens ont durci les règles de nommage des fonds. Un sujet d'actualité permanent en gestion d'actifs."},{"t":"macro","q":"À quoi sert un taux directeur de banque centrale ?","r":"À régler le prix de l'argent court terme pour piloter l'inflation et l'activité.","x":"Le canal est indirect : taux plus hauts, crédit plus cher, demande qui ralentit, prix qui décélèrent. Il faut douze à dix-huit mois pour que ça se voie."},{"t":"macro","q":"Quel est le mandat de la BCE ?","r":"La stabilité des prix, définie comme une inflation de 2 pour cent à moyen terme, symétrique.","x":"Symétrique veut dire qu'une inflation trop basse est aussi un échec. La Fed, elle, a un double mandat avec l'emploi."},{"t":"macro","q":"Où vérifier le niveau actuel des taux de la BCE ?","r":"Sur le site de la BCE, page des taux directeurs, ou sur celui de la Banque de France.","x":"Trois taux à distinguer : dépôt, refinancement principal, prêt marginal. Le marché suit surtout le taux de dépôt."},{"t":"macro","q":"Qu'est-ce que l'inflation sous-jacente ?","r":"L'inflation hors énergie et alimentation, les postes les plus volatils.","x":"C'est celle que regardent les banques centrales, parce qu'elle reflète la tendance de fond et pas un choc pétrolier."},{"t":"macro","q":"Comment se mesure l'inflation en France et en Europe ?","r":"IPC pour l'indice national de l'INSEE, IPCH pour l'indice harmonisé qui permet la comparaison européenne.","x":"L'écart vient surtout du traitement du logement des propriétaires. Toujours dire lequel on cite."},{"t":"macro","q":"Qu'est-ce que la désinflation, la déflation et la stagflation ?","r":"Désinflation : les prix montent moins vite. Déflation : ils baissent. Stagflation : inflation forte et croissance nulle.","x":"Confusion très fréquente entre désinflation et déflation. La première est un objectif, la seconde une catastrophe."},{"t":"macro","q":"Pourquoi la déflation est-elle dangereuse ?","r":"Elle pousse à reporter les achats, alourdit le poids réel des dettes et fait baisser les salaires.","x":"C'est le piège japonais des années 1990. Une banque centrale la craint plus qu'une inflation modérée."},{"t":"macro","q":"Qu'est-ce que le PIB et ce qu'il ne mesure pas ?","r":"La valeur ajoutée produite sur un territoire. Il ignore le travail non marchand, les inégalités et l'épuisement des ressources.","x":"Trois approches équivalentes : production, demande, revenus. Savoir les citer distingue un candidat."},{"t":"macro","q":"Qu'est-ce que la croissance potentielle ?","r":"Le rythme de croissance soutenable sans accélérer l'inflation, déterminé par la population active et la productivité.","x":"C'est pour ça que la démographie et la productivité sont les deux vrais sujets de long terme, pas les taux."},{"t":"macro","q":"Qu'est-ce que le déficit public et la dette publique ?","r":"Le déficit est un flux annuel, la dette est le stock accumulé.","x":"Critères de Maastricht : 3 pour cent du PIB pour le déficit, 60 pour cent pour la dette. Ce sont des références, pas des lois automatiques."},{"t":"macro","q":"Comment vérifier le déficit et la dette de la France ?","r":"Sur le site de l'INSEE pour les comptes nationaux, et sur celui de l'Agence France Trésor pour la dette négociable.","x":"Eurostat publie les données comparables entre pays. C'est la source à citer en entretien international."},{"t":"macro","q":"Qu'est-ce que la charge de la dette ?","r":"Le montant des intérêts payés chaque année par l'État.","x":"Elle réagit avec retard aux taux, car la dette se refinance progressivement. C'est ce qui rend l'effet des hausses de taux si durable."},{"t":"macro","q":"Qu'est-ce que l'Agence France Trésor ?","r":"L'organisme qui émet et gère la dette de l'État français.","x":"Elle publie son programme d'émission en début d'année. Les adjudications d'OAT ont lieu selon un calendrier connu à l'avance."},{"t":"macro","q":"Qu'est-ce qu'une adjudication d'OAT ?","r":"Une vente aux enchères de titres d'État auprès des spécialistes en valeurs du Trésor.","x":"Le taux de couverture, montant demandé sur montant servi, indique l'appétit du marché. Un taux faible est un signal de tension."},{"t":"macro","q":"Qu'est-ce qu'une agence de notation souveraine ?","r":"Elle note la capacité d'un État à rembourser. Standard and Poor's, Moody's, Fitch sont les trois grandes.","x":"Les dates de revue sont publiées à l'avance. Une dégradation renchérit le financement de tout le pays, entreprises comprises."},{"t":"macro","q":"Pourquoi le spread OAT-Bund monte-t-il ?","r":"Quand le marché perçoit plus de risque budgétaire ou politique en France qu'en Allemagne.","x":"C'est l'indicateur à citer pour parler de la France sans avancer de chiffre incertain. Sa direction compte plus que son niveau."},{"t":"macro","q":"Qu'est-ce que le chômage au sens du BIT ?","r":"Sans emploi, disponible sous deux semaines, et ayant cherché activement dans le mois.","x":"Différent des inscrits à France Travail. Deux chiffres différents, deux définitions, ne jamais les mélanger."},{"t":"macro","q":"Qu'est-ce que le taux d'emploi et le taux d'activité ?","r":"Emploi : part des personnes en emploi dans la population en âge de travailler. Activité : part de celles en emploi ou au chômage.","x":"Un chômage qui baisse parce que des gens renoncent à chercher n'est pas une bonne nouvelle. Le taux d'activité le révèle."},{"t":"macro","q":"Qu'est-ce que la balance commerciale et la balance courante ?","r":"Commerciale : biens et services. Courante : on ajoute les revenus et les transferts.","x":"La France a un déficit commercial structurel compensé en partie par les services et les revenus d'investissement."},{"t":"macro","q":"Qu'est-ce qu'un choc d'offre et un choc de demande ?","r":"Offre : la production devient plus difficile ou plus chère. Demande : la consommation ou l'investissement varie.","x":"Un choc d'offre fait monter les prix ET baisser l'activité. C'est pourquoi il est si difficile à traiter par la politique monétaire."},{"t":"macro","q":"Qu'est-ce que la politique budgétaire par rapport à la politique monétaire ?","r":"Budgétaire : dépenses et impôts, décidée par l'État. Monétaire : taux et liquidité, décidée par la banque centrale indépendante.","x":"En zone euro, la monnaie est commune mais les budgets sont nationaux. C'est le déséquilibre fondamental de la construction."},{"t":"macro","q":"Qu'est-ce que la règle des trois pour cent ?","r":"Le plafond de déficit public rapporté au PIB fixé par le traité de Maastricht.","x":"Les règles budgétaires européennes ont été réformées en 2024 avec des trajectoires pluriannuelles par pays. Vérifier l'état du cadre avant d'en parler."},{"t":"macro","q":"Qu'est-ce que le taux de change effectif ?","r":"La valeur d'une monnaie face à un panier de devises pondéré par les échanges.","x":"Plus pertinent que le seul euro-dollar pour juger de la compétitivité. C'est ce que publie la BCE."},{"t":"macro","q":"Comment une hausse de l'euro affecte-t-elle une entreprise exportatrice ?","r":"Elle rend ses produits plus chers hors zone euro et réduit la valeur en euros de ses ventes en devises.","x":"Effet double : compétitivité et conversion. Une bonne réponse d'entretien distingue les deux."},{"t":"macro","q":"Qu'est-ce que le prix du baril et pourquoi il compte encore ?","r":"Le prix du pétrole brut, référence Brent en Europe. Il se diffuse dans les transports, la chimie, l'agriculture.","x":"Vérifier le niveau du jour avant tout entretien. C'est la question de culture générale la plus posée en finance."},{"t":"macro","q":"Qu'est-ce que l'effet de second tour de l'inflation ?","r":"Quand la hausse des prix se transmet aux salaires, qui alimentent à leur tour les prix.","x":"C'est ce que les banques centrales veulent absolument éviter. D'où leur attention aux négociations salariales."},{"t":"macro","q":"Qu'est-ce que l'indexation des salaires ?","r":"Un mécanisme automatique liant les salaires à l'inflation.","x":"La France l'a supprimé en 1983, sauf pour le SMIC qui reste partiellement indexé. La Belgique l'a conservé."},{"t":"macro","q":"Qu'est-ce que la productivité globale des facteurs ?","r":"La part de la croissance qui ne s'explique ni par le capital ni par le travail. En pratique, le progrès technique et l'organisation.","x":"Son ralentissement dans les pays développés est un des grands débats économiques actuels."},{"t":"macro","q":"Qu'est-ce qu'une récession technique ?","r":"Deux trimestres consécutifs de baisse du PIB.","x":"C'est une convention de presse, pas une définition officielle. Aux États-Unis, c'est un comité du NBER qui date les récessions."},{"t":"macro","q":"Qu'est-ce que le cycle économique ?","r":"L'alternance d'expansion, ralentissement, récession et reprise.","x":"Les secteurs n'y réagissent pas de la même façon. Le luxe et l'automobile sont cycliques, la santé et l'alimentaire défensifs."},{"t":"macro","q":"Qu'est-ce qu'un secteur défensif et un secteur cyclique ?","r":"Défensif : la demande varie peu avec le cycle, comme la santé ou l'alimentaire. Cyclique : elle varie fortement, comme l'automobile.","x":"C'est le premier filtre d'une allocation. Un assureur non-vie privilégie les défensifs parce que son passif est court."},{"t":"macro","q":"Qu'est-ce que la prime de risque pays ?","r":"Le supplément de rendement exigé pour investir dans un pays donné, lié au risque politique et de convertibilité.","x":"On l'ajoute au taux d'actualisation dans un DCF sur un pays émergent. Damodaran publie des estimations gratuites."},{"t":"macro","q":"Qu'est-ce que le carry trade ?","r":"Emprunter dans une devise à taux bas pour placer dans une devise à taux élevé.","x":"Il rapporte tant que le change ne bouge pas, et se dénoue brutalement quand il bouge. Source classique de crises de change."},{"t":"macro","q":"Qu'est-ce que la fragmentation en zone euro ?","r":"L'écartement des conditions de financement entre pays membres malgré une politique monétaire unique.","x":"La BCE a créé des outils anti-fragmentation pour y répondre. Sujet récurrent dès que le spread français ou italien s'écarte."},{"t":"macro","q":"Qu'est-ce que le mécanisme européen de stabilité ?","r":"Le fonds de secours de la zone euro, qui prête aux États en difficulté sous conditions.","x":"Créé après la crise grecque. Il n'est presque plus utilisé mais il reste l'assurance de dernier recours."},{"t":"macro","q":"Qu'est-ce que le plan NextGenerationEU ?","r":"Le plan de relance européen financé par un emprunt commun, distribué en subventions et prêts.","x":"C'est la première dette commune européenne d'ampleur. Un précédent institutionnel majeur, à connaître."},{"t":"macro","q":"Qu'est-ce que la transition énergétique du point de vue financier ?","r":"Un besoin d'investissement massif et durable, financé en partie par les marchés obligataires verts.","x":"Deux risques nommés par les régulateurs : le risque physique, celui des événements climatiques, et le risque de transition, celui des actifs échoués."},{"t":"macro","q":"Qu'est-ce qu'un actif échoué ?","r":"Un actif qui perd sa valeur avant la fin de sa vie économique à cause d'un changement de réglementation ou de technologie.","x":"Une centrale à charbon en est l'exemple type. C'est le cœur du risque de transition pour un investisseur de long terme."},{"t":"macro","q":"Qu'est-ce qu'une obligation verte ?","r":"Une obligation dont le produit finance des projets environnementaux identifiés, avec reporting d'impact.","x":"Le standard européen EU Green Bond est volontaire. Le greenium, l'écart de taux favorable, existe mais reste faible."},{"t":"macro","q":"Comment se tenir informé sérieusement en quinze minutes par jour ?","r":"Un quotidien économique le matin, les communiqués de la BCE et de l'INSEE, et une lettre sectorielle hebdomadaire.","x":"Le piège est de tout lire. Mieux vaut trois sources suivies tous les jours que vingt suivies une fois."},{"t":"macro","q":"Quelles sources gratuites et fiables pour un candidat en finance ?","r":"INSEE, Banque de France, BCE, Eurostat, AMF, ACPR, France Assureurs, et les communiqués des sociétés cotées.","x":"Citer une source primaire en entretien vaut mieux que citer un article. Ça montre qu'on remonte au chiffre."},{"t":"macro","q":"Comment parler d'actualité en entretien sans se tromper ?","r":"En donnant la tendance et le mécanisme, pas un chiffre précis dont on n'est pas certain.","x":"Formule sûre : « les taux se sont détendus depuis le pic, ce qui allège le refinancement des entreprises endettées ». Vrai et vérifiable."},{"t":"macro","q":"Que répondre à « quelle actualité économique vous a marqué récemment ? »","r":"Un sujet, pourquoi il compte pour l'entreprise en face, et une conséquence concrète sur son métier.","x":"Le lien avec l'entreprise est ce qui compte. Un candidat qui récite l'actualité sans la relier au poste ne marque pas de point."},{"t":"macro","q":"Qu'est-ce que le coût du capital dans un contexte de taux plus élevés ?","r":"Il monte, donc les projets doivent rapporter davantage pour être acceptés, et les valorisations baissent.","x":"C'est le lien direct entre macro et corporate finance. Savoir le faire en une phrase est un vrai signal de maturité."},{"t":"macro","q":"Pourquoi les valeurs de croissance souffrent-elles quand les taux montent ?","r":"Parce que leurs flux sont lointains, donc plus sensibles à l'actualisation.","x":"Mécaniquement, plus les flux sont éloignés, plus le facteur d'actualisation les écrase. C'est de l'arithmétique, pas une opinion de marché."},{"t":"reg","q":"Qu'est-ce que l'ACPR ?","r":"L'Autorité de contrôle prudentiel et de résolution, qui supervise banques et assurances en France.","x":"Adossée à la Banque de France. À ne pas confondre avec l'AMF, qui supervise les marchés et la protection de l'épargne investie."},{"t":"reg","q":"Qu'est-ce que l'AMF ?","r":"L'Autorité des marchés financiers : elle régule les marchés, agrée les sociétés de gestion et protège les épargnants.","x":"Elle délivre aussi la certification AMF, obligatoire pour certains métiers. Un vrai plus sur un CV finance junior."},{"t":"reg","q":"Que fait un dépositaire ?","r":"Il conserve les actifs d'un fonds et contrôle la régularité des décisions du gérant.","x":"Sa responsabilité de restitution est quasi automatique. C'est ce qui a coûté cher à certains dépositaires après l'affaire Madoff."},{"t":"reg","q":"Qu'est-ce que Solvabilité II ?","r":"Le cadre prudentiel européen des assureurs, en trois piliers : exigences quantitatives, gouvernance, transparence.","x":"Le pilier 1 porte le SCR et le MCR, le pilier 2 l'ORSA, le pilier 3 le reporting. Structure à réciter sans hésiter."},{"t":"reg","q":"Qu'est-ce que le SCR ?","r":"Le capital de solvabilité requis, calibré pour absorber un choc bicentenaire sur un an.","x":"Formellement une valeur en risque à 99,5 pour cent à horizon un an. La formulation exacte est attendue."},{"t":"reg","q":"Qu'est-ce que le MCR ?","r":"Le minimum de capital requis, entre 25 et 45 pour cent du SCR, avec un plancher absolu en euros.","x":"Sous le SCR, l'assureur remet un plan. Sous le MCR, c'est l'agrément qui est en jeu. Deux niveaux de gravité très différents."},{"t":"reg","q":"Qu'est-ce que l'ORSA ?","r":"L'évaluation interne et prospective des risques et de la solvabilité, faite par l'assureur lui-même.","x":"C'est le cœur du pilier 2. Prospectif est le mot clé : on projette, on ne constate pas."},{"t":"reg","q":"Qu'est-ce que la formule standard en Solvabilité II ?","r":"Le calcul réglementaire du SCR par modules de risque, avec des chocs calibrés et une matrice de corrélation.","x":"Ce n'est pas un modèle de risque, c'est un barème. Un choc de 39 pour cent sur les actions ne dit pas qu'une baisse de 39 est probable."},{"t":"reg","q":"Quels chocs applique la formule standard aux principales classes d'actifs ?","r":"Zéro sur les souveraines de l'Espace économique européen en monnaie locale, environ 15 sur les obligations d'entreprises, 25 sur l'immobilier, 39 sur les actions de type 1.","x":"Le 39 bouge entre 29 et 49 avec l'ajustement symétrique. Un sous-module actions de long terme existe à 22 pour cent."},{"t":"reg","q":"Qu'est-ce que l'ajustement symétrique ?","r":"Un correcteur qui fait varier le choc actions de plus ou moins 10 points selon l'écart du marché à sa moyenne longue.","x":"Il est contracyclique : il durcit quand le marché est haut, il assouplit quand il a chuté."},{"t":"reg","q":"Pourquoi le choc de spread est-il nul sur les dettes souveraines européennes ?","r":"C'est un choix du régulateur, pas une mesure du risque réel.","x":"Nul en spread ne veut pas dire nul en taux. Le module taux s'applique toujours. Piège d'entretien classique."},{"t":"reg","q":"Qu'est-ce que la capacité d'absorption des pertes ?","r":"La réduction du SCR liée aux impôts différés et à la participation aux bénéfices des assurés.","x":"Elle est bien plus forte en vie qu'en non-vie, où il y a peu de participation aux bénéfices."},{"t":"reg","q":"Quelle différence entre un passif vie et un passif non-vie ?","r":"Vie : long, montant connu, souvent avec taux garanti et possibilité de rachat. Non-vie : court, montant incertain, sensible à l'inflation des sinistres.","x":"Cette différence commande toute la gestion d'actifs. C'est la phrase de cadrage à sortir en premier."},{"t":"reg","q":"Qu'est-ce que l'inflation des sinistres ?","r":"La hausse du coût de règlement des sinistres déjà provisionnés : pièces, main d'œuvre, indemnisation corporelle.","x":"C'est le vrai risque d'un assureur non-vie, souvent plus lourd qu'un choc de taux. La couverture principale est la tarification annuelle."},{"t":"reg","q":"Qu'est-ce que la duration d'un passif d'assurance ?","r":"La durée moyenne pondérée des flux de règlement attendus.","x":"Deux à quatre ans en non-vie, huit à douze ans en vie. L'écart avec la duration de l'actif s'appelle le gap de duration."},{"t":"reg","q":"Qu'est-ce que la gestion actif-passif ?","r":"Adosser la structure des placements aux engagements : durée, devise, liquidité, indexation.","x":"Le principe fondateur : le passif commande l'actif. Un gérant institutionnel ne part jamais du rendement."},{"t":"reg","q":"Qu'est-ce que la réserve de capitalisation ?","r":"Une réserve française qui neutralise les plus et moins-values de cession d'obligations dans le résultat.","x":"Elle empêche de doper un résultat en vendant les obligations gagnantes. Un mécanisme purement français, à connaître."},{"t":"reg","q":"Qu'est-ce que la provision pour participation aux bénéfices ?","r":"Une partie des produits financiers mise en réserve pour être redistribuée aux assurés dans les huit ans.","x":"Elle sert d'amortisseur entre les bonnes et les mauvaises années. Un vrai levier de pilotage du taux servi."},{"t":"reg","q":"Qu'est-ce que la loi Sapin 2 pour l'assurance vie ?","r":"Elle permet au HCSF de suspendre temporairement les rachats en cas de menace grave sur la stabilité financière.","x":"Jamais activée à ce jour. Sa seule existence change le comportement des assureurs et rassure le régulateur."},{"t":"reg","q":"Qu'est-ce que le HCSF ?","r":"Le Haut Conseil de stabilité financière, autorité macroprudentielle française.","x":"Il fixe aussi les règles d'octroi du crédit immobilier : taux d'effort et durée maximale."},{"t":"reg","q":"Qu'est-ce que Bâle III ?","r":"Le cadre prudentiel bancaire : plus de fonds propres, ratios de liquidité et de levier.","x":"Les trois ratios à citer : CET1 pour la solvabilité, LCR pour la liquidité à trente jours, NSFR pour le financement stable."},{"t":"reg","q":"Qu'est-ce que le ratio CET1 ?","r":"Common equity tier 1 : les fonds propres de meilleure qualité rapportés aux actifs pondérés par les risques.","x":"C'est le ratio que citent tous les communiqués bancaires. Le comparer d'une banque à l'autre suppose des modèles de risque comparables."},{"t":"reg","q":"Qu'est-ce que le LCR ?","r":"Liquidity coverage ratio : les actifs liquides doivent couvrir les sorties nettes de trésorerie sur trente jours de stress.","x":"Il répond directement à 2008, où des banques solvables sont mortes par manque de liquidité."},{"t":"reg","q":"Qu'est-ce que les actifs pondérés par les risques ?","r":"Les expositions multipliées par un coefficient de risque, base de calcul des ratios de solvabilité.","x":"Un prêt d'État bien noté pèse peu, un crédit d'entreprise pèse beaucoup. C'est là que se logent les débats sur les modèles internes."},{"t":"reg","q":"Qu'est-ce que le risque de crédit, de marché et opérationnel ?","r":"Crédit : la contrepartie ne paie pas. Marché : les prix bougent. Opérationnel : défaillance de processus, de personnes ou de systèmes.","x":"Les trois piliers du calcul de fonds propres bancaires. Le risque opérationnel inclut la fraude et le risque juridique."},{"t":"reg","q":"Qu'est-ce que le risque de liquidité ?","r":"L'incapacité à honorer ses engagements faute de trouver des fonds, même en étant solvable.","x":"La distinction solvabilité et liquidité est la question de base de tout entretien en banque ou en assurance."},{"t":"reg","q":"Qu'est-ce que le risque de contrepartie ?","r":"Le risque qu'une partie à un contrat dérivé fasse défaut avant l'échéance.","x":"Traité par les appels de marge et la compensation centrale. C'est ce que la réforme EMIR a organisé après 2008."},{"t":"reg","q":"Qu'est-ce que les trois lignes de défense ?","r":"Première : les opérationnels qui contrôlent leur propre travail. Deuxième : le contrôle indépendant, risques et conformité. Troisième : l'audit interne.","x":"Modèle universel en banque, assurance et grands groupes. À citer dès qu'on parle de contrôle interne."},{"t":"reg","q":"Qu'est-ce que la conformité, ou compliance ?","r":"La fonction qui veille au respect des règles externes et internes, et au risque de non-conformité.","x":"Elle est indépendante et a un accès direct à la direction. Son avis peut bloquer une opération, c'est ce qui fait sa force."},{"t":"reg","q":"Qu'est-ce que la LCB-FT ?","r":"Lutte contre le blanchiment de capitaux et le financement du terrorisme.","x":"Elle impose de connaître son client, de surveiller les opérations et de déclarer les soupçons à Tracfin."},{"t":"reg","q":"Qu'est-ce que le KYC ?","r":"Know your customer : l'identification et la vérification du client et de son bénéficiaire effectif.","x":"L'approche est fondée sur les risques. Un client politiquement exposé déclenche des vigilances renforcées."},{"t":"reg","q":"Qu'est-ce que Tracfin ?","r":"La cellule française de renseignement financier qui reçoit les déclarations de soupçon.","x":"La déclaration est confidentielle et il est interdit d'informer le client. Point de droit à connaître."},{"t":"reg","q":"Qu'est-ce que MIF 2 ?","r":"La directive européenne sur les marchés d'instruments financiers : transparence, protection de l'investisseur, gouvernance produit.","x":"Elle a imposé le test d'adéquation et la transparence sur les frais. C'est elle qui a fait apparaître les rétrocessions au grand jour."},{"t":"reg","q":"Qu'est-ce que le devoir de conseil ?","r":"L'obligation de recommander un produit adapté à la situation, aux objectifs et à la connaissance du client.","x":"Sa preuve est écrite. Sans questionnaire signé et conservé, le professionnel est démuni en cas de litige."},{"t":"reg","q":"Qu'est-ce que le RGPD en contexte financier ?","r":"Le règlement européen sur les données personnelles : base légale, minimisation, durée de conservation, droits des personnes.","x":"Le point sensible en finance est le croisement de données pour le scoring, qui touche à la décision automatisée."},{"t":"reg","q":"Qu'est-ce que DORA ?","r":"Le règlement européen sur la résilience opérationnelle numérique du secteur financier.","x":"Il encadre le risque informatique et la dépendance aux prestataires cloud. Sujet très présent dans les recrutements risques depuis 2025."},{"t":"reg","q":"Qu'est-ce que la réassurance ?","r":"L'assurance des assureurs : une partie du risque est cédée à un réassureur.","x":"Elle protège surtout contre les sinistres extrêmes et permet de souscrire plus que ses fonds propres ne le permettraient seuls."},{"t":"reg","q":"Quelle différence entre réassurance proportionnelle et non proportionnelle ?","r":"Proportionnelle : le réassureur prend un pourcentage des primes et des sinistres. Non proportionnelle : il n'intervient qu'au-delà d'un seuil.","x":"L'excédent de sinistre, ou excess of loss, est la forme non proportionnelle la plus courante."},{"t":"reg","q":"Qu'est-ce que le ratio combiné en assurance non-vie ?","r":"Sinistres plus frais, rapportés aux primes acquises.","x":"En dessous de 100 pour cent, la souscription est rentable avant les produits financiers. C'est l'indicateur roi du non-vie."},{"t":"reg","q":"Qu'est-ce que la provision pour sinistres à payer ?","r":"L'estimation du coût des sinistres survenus mais pas encore réglés, y compris ceux non encore déclarés.","x":"Les IBNR, incurred but not reported, en font partie. Leur estimation par chain ladder est un classique actuariel."},{"t":"reg","q":"Qu'est-ce que la méthode chain ladder ?","r":"Une méthode de provisionnement qui projette les règlements futurs à partir des cadences observées dans le passé.","x":"Elle suppose que le passé se répète. Une inflation nouvelle ou un changement de jurisprudence la rend fausse."},{"t":"data","q":"Quelle est la différence entre RECHERCHEV et INDEX EQUIV ?","r":"RECHERCHEV cherche toujours à droite de la colonne de recherche. INDEX EQUIV cherche dans n'importe quel sens et ne casse pas si on insère une colonne.","x":"Depuis Excel 365, RECHERCHEX fait les deux. Savoir dire pourquoi INDEX EQUIV reste plus robuste sur les vieux fichiers marque des points."},{"t":"data","q":"Que fait SOMME.SI.ENS ?","r":"Elle somme une plage selon plusieurs critères simultanés.","x":"Toujours préférer les versions ENS aux versions simples. Elles acceptent un critère aujourd'hui et cinq demain sans réécrire la formule."},{"t":"data","q":"Qu'est-ce qu'une référence absolue et relative ?","r":"Le dollar fige la ligne ou la colonne lors d'une recopie. A1 bouge, $A$1 non.","x":"F4 fait défiler les quatre combinaisons. Une formule mal figée est la première cause d'erreur dans un fichier repris."},{"t":"data","q":"Qu'est-ce qu'un tableau croisé dynamique ?","r":"Un outil d'agrégation qui regroupe et calcule des données par dimensions, sans écrire de formule.","x":"Sa limite : il fige la source. Le brancher sur un tableau structuré, avec Ctrl L, fait que la plage s'étend toute seule."},{"t":"data","q":"À quoi sert Power Query ?","r":"À importer, nettoyer et transformer des données de façon reproductible, avec les étapes enregistrées.","x":"C'est l'outil qui remplace le copier-coller mensuel. Une fois la requête écrite, la mise à jour prend un clic."},{"t":"data","q":"Qu'est-ce que Power Pivot et le modèle de données ?","r":"Un moteur qui relie plusieurs tables par des relations et calcule des mesures en DAX.","x":"Il permet de croiser un fichier de ventes et un référentiel client sans faire un seul RECHERCHEV."},{"t":"data","q":"Qu'est-ce que le DAX ?","r":"Le langage de formules de Power BI et Power Pivot.","x":"La fonction à connaître est CALCULATE, qui modifie le contexte de filtre. C'est elle qui fait tout le pouvoir du langage."},{"t":"data","q":"Quelle différence entre Power BI et Excel ?","r":"Excel est un outil de calcul et d'analyse ponctuelle. Power BI est un outil de restitution partagée et rafraîchie automatiquement.","x":"Bonne réponse en entretien : Excel pour construire et tester, Power BI pour diffuser à vingt personnes sans envoyer vingt fichiers."},{"t":"data","q":"Qu'est-ce qu'une table de faits et une table de dimensions ?","r":"La table de faits contient les mesures, les tables de dimensions contiennent les attributs qui servent à filtrer.","x":"C'est le modèle en étoile. Le respecter rend les rapports rapides et les formules simples."},{"t":"data","q":"Qu'est-ce qu'une clé primaire et une clé étrangère ?","r":"La clé primaire identifie de façon unique une ligne. La clé étrangère pointe vers la clé primaire d'une autre table.","x":"En finance, la clé étrangère la plus utile est le code société ou le code analytique. S'assurer qu'il est unique évite des doublons invisibles."},{"t":"data","q":"Qu'est-ce qu'un ERP ?","r":"Un progiciel qui gère l'ensemble des processus sur une base unique : achats, ventes, stocks, comptabilité, paie.","x":"SAP, Oracle, Microsoft Dynamics, Sage, Cegid. Citer celui de l'entreprise en entretien montre que vous avez préparé."},{"t":"data","q":"Qu'est-ce que SAP S4 HANA ?","r":"La version récente de l'ERP SAP, sur base de données en mémoire.","x":"Les migrations vers S4 sont un gros marché de conseil actuellement. Le savoir donne un sujet de conversation en entretien."},{"t":"data","q":"Qu'est-ce qu'un outil EPM ou CPM ?","r":"Enterprise performance management : les outils de budget, de consolidation et de reporting groupe.","x":"Anaplan, Tagetik, OneStream, Board. Si l'offre les cite, aller lire ce que fait l'outil avant l'entretien."},{"t":"data","q":"Qu'est-ce qu'une API ?","r":"Une interface qui permet à deux logiciels d'échanger des données automatiquement.","x":"Dire qu'on a déjà consommé une API, même simple, distingue immédiatement un profil finance de ses concurrents."},{"t":"data","q":"Qu'est-ce que le format JSON ?","r":"Un format texte structuré en paires clé-valeur, standard des échanges par API.","x":"Il se lit dans Power Query. Savoir aplatir un JSON imbriqué en tableau est une compétence concrète et rare en finance."},{"t":"data","q":"Qu'est-ce que le format CSV et son piège principal ?","r":"Un fichier texte à séparateurs. Le piège est le séparateur décimal et le point-virgule français contre la virgule anglaise.","x":"Second piège : l'encodage. Un fichier en UTF-8 ouvert en ANSI transforme les accents en caractères illisibles."},{"t":"data","q":"Qu'est-ce que le SQL et à quoi il sert en finance ?","r":"Le langage d'interrogation des bases de données. Il sert à extraire soi-même sa donnée sans dépendre de l'informatique.","x":"Quatre mots-clés suffisent pour commencer : SELECT, FROM, WHERE, GROUP BY. C'est déjà 80 pour cent des besoins."},{"t":"data","q":"Que fait une jointure SQL ?","r":"Elle combine deux tables sur une clé commune. INNER garde les correspondances, LEFT garde tout de la table de gauche.","x":"En finance, la LEFT JOIN est la plus utile : elle montre ce qui n'a PAS de correspondance, donc les anomalies."},{"t":"data","q":"Qu'est-ce que Python peut apporter à un contrôleur de gestion ?","r":"Automatiser les tâches répétitives : consolider des fichiers, produire des rapports, appeler des API.","x":"Trois bibliothèques à citer : pandas pour les données, openpyxl pour Excel, requests pour les API."},{"t":"data","q":"Qu'est-ce que le VBA et quand il reste pertinent ?","r":"Le langage de macro d'Excel. Il reste pertinent quand l'outil doit vivre dans un classeur, sans installation.","x":"Argument à donner en entretien : Python est plus puissant, VBA est plus déployable dans une PME sans informatique."},{"t":"data","q":"Qu'est-ce que la qualité de données et comment on la mesure ?","r":"Complétude, exactitude, cohérence, fraîcheur, unicité.","x":"Un tableau de bord de qualité de données avec ces cinq axes fait bonne impression et se construit en une journée."},{"t":"data","q":"Qu'est-ce qu'un doublon et comment le détecter proprement ?","r":"Deux lignes qui représentent le même fait. On les détecte par une clé métier, pas par une identité stricte de toutes les colonnes.","x":"Exemple : même fournisseur, même montant, même date, numéro de facture différent. C'est souvent une double saisie."},{"t":"data","q":"Qu'est-ce que la piste d'audit ?","r":"La possibilité de remonter d'un chiffre agrégé jusqu'à la pièce justificative.","x":"Elle est une obligation légale en comptabilité. Dans un fichier de reporting, elle se traduit par la traçabilité de chaque étape."},{"t":"data","q":"Comment fiabiliser un classeur qui sert à plusieurs personnes ?","r":"Séparer les onglets de données, de calcul et de restitution, protéger les formules, et ne saisir que dans des cellules identifiées.","x":"Règle simple : une cellule bleue se saisit, une cellule noire se calcule. Tout le monde comprend en dix secondes."},{"t":"data","q":"Qu'est-ce qu'un contrôle de cohérence automatique dans un fichier ?","r":"Une formule qui compare deux chemins de calcul et affiche OK ou ÉCART.","x":"Le mettre en haut de l'onglet, visible. Un fichier qui se contrôle lui-même vaut mieux qu'un fichier qu'on relit."},{"t":"data","q":"Qu'est-ce que la mise en forme conditionnelle bien utilisée ?","r":"Un signal visuel réservé à ce qui appelle une action, jamais une décoration.","x":"Trois couleurs maximum. Un tableau entièrement colorié ne transmet plus aucune information."},{"t":"data","q":"Qu'est-ce qu'un graphique en cascade et à quoi il sert ?","r":"Un graphique qui décompose un passage d'un chiffre à un autre par contributions positives et négatives.","x":"C'est LE graphique du contrôle de gestion : passage du budget au réalisé, ou de l'EBITDA N-1 à celui de N."},{"t":"data","q":"Quel graphique choisir pour une évolution dans le temps ?","r":"Une courbe. Les barres servent aux comparaisons entre catégories, pas au temps.","x":"Et jamais de camembert au-delà de cinq parts. L'oeil ne compare pas des angles."},{"t":"data","q":"Qu'est-ce qu'un axe tronqué et pourquoi c'est un piège ?","r":"Un axe qui ne part pas de zéro et qui exagère visuellement les écarts.","x":"Acceptable sur une courbe de taux, malhonnête sur des barres. Le savoir vous protège de vous faire manipuler."},{"t":"data","q":"Qu'est-ce que la règle des trois clics dans un tableau de bord ?","r":"Toute information importante doit être atteignable en trois clics maximum.","x":"Au-delà, personne ne va la chercher. C'est ce qui distingue un tableau de bord utilisé d'un tableau de bord produit."},{"t":"data","q":"Qu'est-ce que Pennylane ?","r":"Un outil français de comptabilité et de gestion financière en ligne, connecté aux banques et aux factures.","x":"Il expose une API. Citer une automatisation faite dessus est un exemple concret et vérifiable en entretien."},{"t":"data","q":"Qu'est-ce qu'un rapprochement automatique bancaire ?","r":"Un moteur qui associe les lignes de banque aux écritures selon des règles de montant, de date et de libellé.","x":"Il traite 80 pour cent des cas. Le travail à valeur ajoutée est sur les 20 pour cent restants, pas sur les 80."},{"t":"data","q":"Qu'est-ce que la RPA ?","r":"Robotic process automation : des robots qui reproduisent des actions humaines dans les logiciels.","x":"Utile quand il n'y a pas d'API. C'est une solution de contournement, plus fragile qu'une intégration réelle."},{"t":"data","q":"Comment utiliser l'IA générative sans risque en finance ?","r":"Pour rédiger, structurer et expliquer, jamais pour produire un chiffre sans le vérifier, et jamais avec des données confidentielles sur un outil public.","x":"Réponse attendue en entretien en 2026. Montrer qu'on connaît l'outil ET ses limites vaut mieux que l'enthousiasme."},{"t":"data","q":"Qu'est-ce qu'un hallucination de modèle et pourquoi ça compte ici ?","r":"Une réponse fausse mais plausible. En finance, un chiffre faux qui a l'air juste est le pire des cas.","x":"La règle : tout chiffre produit par un outil doit être retrouvé dans la source avant d'être diffusé."},{"t":"data","q":"Qu'est-ce que la sauvegarde 3-2-1 ?","r":"Trois copies, sur deux supports différents, dont une hors site.","x":"Applicable même à un fichier de budget. Un classeur perdu la veille d'un comité coûte plus cher qu'un disque dur."},{"t":"data","q":"Qu'est-ce que le contrôle d'accès par les rôles ?","r":"On donne des droits à un rôle, pas à une personne, et on affecte les personnes aux rôles.","x":"Cela survit aux départs et aux arrivées. C'est ce que demandera un auditeur informatique."},{"t":"data","q":"Qu'est-ce qu'une trace d'audit dans un ERP ?","r":"L'enregistrement de qui a fait quoi et quand, non modifiable.","x":"Un ERP qui laisse modifier une écriture validée sans trace n'est pas conforme aux exigences fiscales françaises."},{"t":"meta","q":"Comment répondre à « parlez-moi de vous » en finance ?","r":"Trois temps : ce que vous faites aujourd'hui avec un chiffre, ce que vous avez construit, ce que vous cherchez.","x":"Deux minutes maximum. Terminer par ce que vous cherchez donne la main à la suite de l'entretien."},{"t":"meta","q":"Comment répondre à « quelle est votre plus grande réussite ? »","r":"Une situation, une action précise que vous avez menée, un résultat chiffré.","x":"Méthode STAR : situation, tâche, action, résultat. Le résultat chiffré est ce qui distingue une vraie réponse."},{"t":"meta","q":"Comment parler d'un échec sans se dévaloriser ?","r":"Un vrai échec, ce que vous en avez tiré, et ce que vous faites différemment depuis.","x":"Éviter les faux échecs du type « je suis trop perfectionniste ». Le recruteur les entend dix fois par jour."},{"t":"meta","q":"Que répondre à « pourquoi nous ? »","r":"Une raison liée à leur activité, une raison liée au poste, une raison liée à ce que vous pouvez leur apporter.","x":"Citer un fait précis sur l'entreprise, pas une valeur affichée sur leur site. Le rapport annuel est une mine."},{"t":"meta","q":"Que répondre à « quelles sont vos prétentions salariales ? »","r":"Une fourchette basée sur le marché, en précisant que le poste et le contenu comptent autant.","x":"Ne jamais donner un chiffre unique. Se renseigner avant sur les grilles de l'APEC ou de Glassdoor pour être crédible."},{"t":"meta","q":"Quelles questions poser en fin d'entretien ?","r":"Sur les priorités des six premiers mois, sur la façon dont la performance est mesurée, sur l'équipe.","x":"Ne jamais dire non merci. Une question montre l'intérêt, et celle sur les six premiers mois vous met déjà dans le poste."},{"t":"meta","q":"Comment expliquer une expérience courte ou une alternance en CDI ?","r":"En parlant du contenu réel et de l'autonomie, pas de la durée.","x":"Une alternance où on tient la comptabilité de huit sociétés vaut mieux qu'un CDI où on saisit des factures. Dire le contenu."},{"t":"meta","q":"Comment gérer la question de la disponibilité ?","r":"On donne la date, jamais la raison.","x":"« Disponible à partir de mi-novembre 2026 » est une information de calendrier. Expliquer pourquoi ouvre une discussion inutile."},{"t":"meta","q":"Qu'est-ce qu'un ATS et pourquoi ça change un CV ?","r":"Un logiciel de tri des candidatures. Il lit le texte, pas la mise en page.","x":"Éviter les tableaux, les zones de texte et les colonnes complexes. Un CV joli qui ne se lit pas est éliminé sans être vu."},{"t":"meta","q":"Quels mots-clés mettre dans un CV finance ?","r":"Ceux de l'annonce, écrits comme dans l'annonce.","x":"Si l'offre dit reporting, écrire reporting et pas tableau de bord. L'ATS ne fait pas de synonymes."},{"t":"meta","q":"Comment chiffrer une ligne de CV quand on n'a pas de gros chiffres ?","r":"On chiffre le périmètre, le délai ou la fréquence, pas seulement les euros.","x":"Huit sociétés, trois semaines, chaque mois en comité de direction : ce sont des chiffres et ils parlent."},{"t":"meta","q":"Combien de temps un recruteur regarde-t-il un CV ?","r":"Quelques dizaines de secondes au premier passage.","x":"D'où la règle : le titre, les trois premières lignes et les intitulés de poste doivent suffire à comprendre le profil."},{"t":"meta","q":"Faut-il mettre une photo sur un CV ?","r":"En France c'est courant et accepté. Au Royaume-Uni, en Irlande, aux États-Unis et au Canada, c'est un motif d'écartement.","x":"D'où l'intérêt d'avoir une version sans photo pour les candidatures anglo-saxonnes."},{"t":"meta","q":"Que met-on dans une lettre de motivation qui n'est pas dans le CV ?","r":"Le lien entre ce que vous avez fait et ce qu'ils cherchent, et une raison précise de les viser eux.","x":"Trois paragraphes suffisent : ce que je fais, pourquoi ce poste, pourquoi vous. Une page maximum."},{"t":"meta","q":"Quel est le meilleur moment pour relancer une candidature ?","r":"Sept à dix jours après l'envoi, une seule fois, en deux lignes.","x":"Deux relances agacent. Une relance datée et courte se remarque sans déranger."},{"t":"meta","q":"À qui écrire dans une entreprise quand on postule ?","r":"Au recrutement pour parler de sa candidature. À un pair ou à un ancien de son école pour comprendre le poste.","x":"Ne jamais annoncer sa candidature à quelqu'un qui n'est pas du recrutement. Cela le met en position d'arbitre et il ne répond pas."},{"t":"meta","q":"Comment aborder un ancien de son école sur LinkedIn ?","r":"En rappelant l'école, en se présentant en deux phrases, et en posant une seule question ouverte.","x":"L'école crée une obligation morale de répondre. C'est le canal au meilleur taux de réponse, de loin."},{"t":"meta","q":"Quelle est la limite d'une note de connexion LinkedIn ?","r":"Environ 300 caractères. Une fois la connexion acceptée, le message n'a plus de limite pratique.","x":"D'où la stratégie en deux temps : une note très courte pour entrer, un vrai message ensuite."},{"t":"meta","q":"Qu'est-ce qu'un InMail et comment ne pas le gâcher ?","r":"Un message LinkedIn Premium vers une personne non connectée. Les crédits sont limités.","x":"L'objet compte plus que le corps : c'est la seule chose visible dans la notification. Viser aussi les profils Open Profile, gratuits."},{"t":"meta","q":"Comment se préparer à un test de calcul mental en entretien finance ?","r":"En travaillant les pourcentages, la règle de trois et les ordres de grandeur, pas les multiplications compliquées.","x":"Ce qu'on teste, c'est la capacité à ne pas se tromper d'un facteur dix sous pression, pas la vitesse pure."},{"t":"meta","q":"Que faire quand on ne sait pas répondre à une question technique ?","r":"Dire ce qu'on sait autour, poser le raisonnement, et reconnaître la limite.","x":"Un recruteur préfère un candidat qui structure et admet, à un candidat qui invente. L'invention se voit immédiatement."},{"t":"meta","q":"Comment présenter une compétence qu'on maîtrise moyennement ?","r":"En donnant le niveau réel et un exemple concret de ce qu'on sait faire avec.","x":"« Je sais faire des tableaux croisés et Power Query, je débute en DAX » est plus crédible que « maîtrise d'Excel »."},{"t":"meta","q":"Qu'est-ce que le test de personnalité en recrutement finance ?","r":"Un questionnaire qui mesure des traits de comportement, souvent utilisé en cabinet et en grands groupes.","x":"Répondre honnêtement et vite. Les tests détectent les réponses incohérentes bien mieux qu'on ne le croit."},{"t":"meta","q":"Qu'est-ce qu'un assessment center ?","r":"Une journée de mise en situation : étude de cas, présentation, entretien croisé, parfois travail en groupe.","x":"En groupe, on est évalué sur la contribution et l'écoute, pas sur la domination de la discussion."},{"t":"meta","q":"Comment traiter une étude de cas financière en entretien ?","r":"Clarifier la question, poser les hypothèses à voix haute, structurer en trois parties, conclure par une recommandation.","x":"Le raisonnement compte plus que le résultat. Dire ses hypothèses est ce qui rassure l'examinateur."},{"t":"meta","q":"Qu'est-ce qu'une période d'essai en CDI cadre ?","r":"Quatre mois, renouvelable une fois si la convention collective le prévoit.","x":"Le renouvellement doit être accepté par écrit avant la fin de la première période. Point souvent ignoré."},{"t":"meta","q":"Qu'est-ce que la convention collective Syntec ?","r":"La convention des bureaux d'études et du conseil, très répandue dans les ESN et le conseil.","x":"Elle fixe les positions et coefficients, qui déterminent le minimum conventionnel. Utile pour négocier en connaissance de cause."},{"t":"meta","q":"Qu'est-ce qu'un forfait jours ?","r":"Un décompte du temps de travail en jours et non en heures, réservé aux cadres autonomes.","x":"Il impose un suivi de la charge et un entretien annuel dédié. Son absence peut le rendre inopposable."},{"t":"meta","q":"Comment se calcule un salaire brut en net approximativement ?","r":"Pour un cadre du privé, environ 22 à 25 pour cent de cotisations salariales.","x":"Repère mental : net égale brut multiplié par 0,77 environ, avant impôt à la source. Suffisant pour discuter une offre."},{"t":"meta","q":"Quelle différence entre coût employeur et salaire brut ?","r":"Le coût employeur ajoute les cotisations patronales, en général 25 à 42 pour cent du brut.","x":"En contrôle de gestion, on raisonne toujours en coût employeur. C'est la donnée qui entre dans le budget."},{"t":"meta","q":"Qu'est-ce que le prélèvement à la source ?","r":"L'impôt sur le revenu retenu directement sur le salaire par l'employeur.","x":"Le taux vient de l'administration, l'employeur ne le calcule pas. Il peut être individualisé ou neutre."},{"t":"meta","q":"Que signifie budget en anglais dans un contexte financier ?","r":"Budget, mais on dit aussi plan. Le forecast est la prévision réactualisée.","x":"Attention au faux ami : actual signifie réalisé, pas actuel. Actuals versus budget, c'est réalisé contre budget."},{"t":"meta","q":"Comment dit-on écart en anglais financier ?","r":"Variance. L'analyse des écarts est la variance analysis.","x":"Ne pas confondre avec la variance statistique. Le contexte tranche, mais le mot est le même."},{"t":"meta","q":"Comment dit-on chiffre d'affaires, résultat et bénéfice en anglais ?","r":"Revenue ou turnover, operating income ou profit, net income.","x":"Turnover en anglais britannique signifie chiffre d'affaires, mais aussi rotation du personnel. Le contexte est essentiel."},{"t":"meta","q":"Comment dit-on compte de résultat et bilan en anglais ?","r":"Income statement ou profit and loss, et balance sheet.","x":"P and L à l'oral. Le tableau de flux est le cash flow statement."},{"t":"meta","q":"Comment dit-on immobilisation, amortissement et provision ?","r":"Fixed asset, depreciation pour le corporel et amortization pour l'incorporel, provision ou accrual.","x":"Depreciation et amortization sont distingués en anglais, d'où le D et le A d'EBITDA."},{"t":"meta","q":"Comment dit-on créances clients et dettes fournisseurs ?","r":"Accounts receivable et accounts payable, souvent abrégés AR et AP.","x":"Le service concerné s'appelle AP team ou AR team. Vocabulaire utile dans un centre de services partagés."},{"t":"meta","q":"Comment dit-on clôture des comptes et cut-off ?","r":"Closing ou month-end close, et cut-off qui s'utilise tel quel en français.","x":"Le fast close se dit pareil dans les deux langues. Le vocabulaire de clôture est très anglicisé."},{"t":"meta","q":"Comment dit-on trésorerie et flux de trésorerie ?","r":"Cash ou treasury pour la fonction, cash flow pour le flux.","x":"Attention : treasury désigne aussi le Trésor public. En entreprise, treasury est la fonction, cash est le solde."},{"t":"meta","q":"Comment dit-on rentabilité et marge ?","r":"Profitability et margin. La rentabilité des capitaux est return.","x":"Return on equity, return on capital employed. Le mot return introduit toujours un ratio de rentabilité."},{"t":"meta","q":"Comment dit-on fonds propres et endettement ?","r":"Equity et debt. Les capitaux propres sont shareholders equity.","x":"Le ratio dette sur fonds propres est le debt to equity ratio, ou gearing en anglais britannique."},{"t":"meta","q":"Comment dit-on prévisionnel et atterrissage ?","r":"Forecast, et pour l'atterrissage on dit full year estimate ou landing.","x":"Year to date signifie cumul depuis le début de l'année, abrégé YTD. À connaître absolument."},{"t":"meta","q":"Que veulent dire YTD, YoY, QoQ et MoM ?","r":"Year to date, year over year, quarter over quarter, month over month.","x":"YoY compare au même mois de l'année précédente, MoM au mois précédent. Confondre les deux fausse toute lecture saisonnière."},{"t":"meta","q":"Que veut dire FY et Q1 dans un communiqué ?","r":"Fiscal year, l'exercice, et premier trimestre.","x":"Attention : l'exercice fiscal ne commence pas partout en janvier. Chez certains, FY26 commence en avril 2025."},{"t":"meta","q":"Que veut dire like for like ?","r":"À périmètre comparable, l'équivalent de croissance organique.","x":"Très utilisé en distribution, où l'on compare les magasins ouverts depuis plus d'un an."},{"t":"meta","q":"Que veut dire run rate ?","r":"L'extrapolation d'une performance récente sur douze mois.","x":"Utile pour parler d'un business qui vient de démarrer. Trompeur s'il y a de la saisonnalité."},{"t":"meta","q":"Que veut dire headcount et FTE ?","r":"Nombre de personnes, et full time equivalent, l'équivalent temps plein.","x":"Deux mi-temps font deux en headcount et un en FTE. Toujours préciser lequel on cite dans un budget."},{"t":"meta","q":"Que veut dire top line et bottom line ?","r":"La première ligne du compte de résultat, le chiffre d'affaires, et la dernière, le résultat net.","x":"Croissance top line sans amélioration bottom line signifie que les coûts suivent le chiffre d'affaires."},{"t":"meta","q":"Que veut dire burn et runway pour une start-up ?","r":"La consommation mensuelle de trésorerie et le nombre de mois de survie.","x":"Question réflexe en entretien dans une start-up : quel est votre runway. Savoir le calculer met en confiance."},{"t":"meta","q":"Que veut dire covenant breach ?","r":"Le non-respect d'un engagement financier envers une banque.","x":"Il déclenche en général une renégociation, un waiver, contre commission. Le mot waiver est à connaître."},{"t":"meta","q":"Comment structurer une réponse en entretien technique ?","r":"Définition en une phrase, formule ou mécanisme, un exemple concret, la limite.","x":"Cette structure en quatre temps fonctionne sur presque toutes les questions techniques. Elle donne l'impression d'un candidat qui a compris, pas appris."},{"t":"meta","q":"Que faire dans les trente premiers jours d'un nouveau poste en finance ?","r":"Comprendre le cycle de clôture, lire les trois derniers reportings, rencontrer les opérationnels, et ne rien changer.","x":"Changer un tableau de bord la première semaine est la meilleure façon de se griller. On observe d'abord."},{"t":"meta","q":"Comment dire non à une demande urgente sans se fâcher ?","r":"En proposant une alternative datée : ce que vous pouvez livrer, quand, et ce qui saute en échange.","x":"Un non sec crée un conflit. Un arbitrage explicite fait de vous quelqu'un de fiable."},{"t":"meta","q":"Quelle est la qualité la plus citée par les recruteurs en contrôle de gestion ?","r":"La capacité à expliquer un chiffre à quelqu'un qui n'est pas financier.","x":"C'est aussi ce qui se travaille le plus vite. Une phrase courte, une comparaison, une conséquence."},{"t":"audit","q":"Qu'est-ce qu'une assertion d'audit ?","r":"Ce que les comptes affirment sans l'écrire : existence, exhaustivité, exactitude, séparation des exercices, évaluation, présentation. Chaque test vise une assertion précise.","x":"En entretien, dis que tu ne testes pas un compte mais une affirmation. Un stock peut exister et être mal valorisé. Ce sont deux assertions et deux tests."},{"t":"audit","q":"Qu'est-ce que le seuil de signification ?","r":"Le montant au-delà duquel une erreur changerait la décision d'un lecteur des comptes. On le fixe en début de mission, souvent un pourcentage du chiffre d'affaires, du résultat ou des capitaux propres.","x":"Il commande tout : la taille des échantillons et la décision de corriger ou non. Une erreur de 400 euros sur un groupe à 300 millions ne se corrige pas."},{"t":"audit","q":"Qu'est-ce que le risque d'audit et quelles sont ses trois composantes ?","r":"Le risque de certifier des comptes faux. Risque inhérent, risque de contrôle, risque de non-détection. Les deux premiers viennent du client, le troisième est le seul que l'auditeur pilote.","x":"Plus le risque du client est élevé, plus l'auditeur doit travailler. C'est ce raisonnement qui justifie le nombre d'heures vendues sur une mission."},{"t":"audit","q":"Qu'est-ce qu'un test de cheminement ?","r":"On prend une opération et on la suit de bout en bout, de la commande jusqu'au règlement et à l'écriture. Le but est de comprendre le processus, pas de compter les erreurs.","x":"C'est toujours la première étape sur un cycle. Le mot anglais, souvent employé tel quel en cabinet, est walkthrough."},{"t":"audit","q":"Qu'est-ce qu'une circularisation ?","r":"Une demande de confirmation envoyée directement à un tiers : banque, client, fournisseur, avocat. La réponse revient à l'auditeur, jamais au client.","x":"La force de la preuve vient de son origine externe. Si la réponse transite par le client, elle ne vaut plus rien."},{"t":"audit","q":"Quelle différence entre un test de procédure et un contrôle de substance ?","r":"Le test de procédure vérifie que le contrôle interne fonctionne. Le contrôle de substance vérifie le montant lui-même, par un rapprochement, un recalcul ou une pièce justificative.","x":"Si les procédures sont fiables, on réduit les contrôles de substance. Sinon on teste tout à la main et la mission coûte plus cher."},{"t":"audit","q":"Qu'est-ce que le référentiel COSO ?","r":"Le cadre de référence du contrôle interne. Cinq composantes : environnement de contrôle, évaluation des risques, activités de contrôle, information et communication, pilotage.","x":"C'est le vocabulaire commun de l'audit interne. Le citer montre que tu sais de quoi tu parles, même sans expérience."},{"t":"audit","q":"Qu'est-ce qu'une FRAP ?","r":"Une feuille de révélation et d'analyse de problème. Quatre blocs : le fait constaté, la cause, la conséquence, la recommandation.","x":"C'est le format de l'audit interne. Une observation sans cause et sans conséquence chiffrée n'est jamais suivie d'effet."},{"t":"audit","q":"Comment choisit-on un échantillon en audit ?","r":"Trois façons combinées : les montants les plus gros, une sélection au hasard sur le reste, et les éléments à risque repérés d'avance.","x":"Le piège classique : ne tester que les gros montants. L'exhaustivité se cache dans les petites lignes et surtout dans ce qui manque."},{"t":"audit","q":"Qu'est-ce qu'une lettre d'affirmation ?","r":"Une lettre signée par la direction en fin de mission. Elle confirme par écrit les informations données à l'auditeur, notamment les litiges et les engagements hors bilan.","x":"Elle ne remplace aucune preuve. Elle engage la responsabilité de la direction sur ce qu'un auditeur ne peut pas vérifier seul."},{"t":"audit","q":"Pourquoi la séparation des tâches est-elle le premier contrôle regardé ?","r":"Parce qu'une même personne ne doit jamais créer un fournisseur, saisir sa facture et la payer. On sépare l'engagement, l'enregistrement et le règlement.","x":"C'est le contrôle qui manque le plus souvent en PME. La fraude au faux fournisseur vit de ce trou-là."},{"t":"audit","q":"Quelle différence entre audit interne et audit externe ?","r":"L'audit externe certifie les comptes pour les tiers, une fois par an. L'audit interne travaille pour la direction, toute l'année, sur tous les processus et pas seulement la finance.","x":"Question de tri très fréquente. Le commissaire aux comptes est indépendant de l'entreprise, l'auditeur interne en est salarié."},{"t":"audit","q":"À quoi ressemble une recommandation d'audit bien écrite ?","r":"Une action, un responsable nommé, une date. Sans ces trois éléments, ce n'est pas une recommandation mais une remarque.","x":"Bon exemple à ressortir si on te demande ce que tu as concrètement amélioré pendant un stage."},{"t":"audit","q":"Qu'est-ce qu'un test de coupure sur les ventes ?","r":"On prend les dernières livraisons avant la clôture et les premières après, et on vérifie que la facture est tombée du bon côté de la date.","x":"C'est le test préféré des auditeurs sur le chiffre d'affaires, parce que c'est là qu'on gonfle un exercice sans effort."},{"t":"audit","q":"Quelles opinions un commissaire aux comptes peut-il rendre ?","r":"La certification sans réserve, la certification avec réserve, le refus de certifier, et l'impossibilité de certifier faute d'éléments suffisants.","x":"La réserve vise un point précis et chiffré. Le refus vise des comptes qui, dans leur ensemble, ne donnent pas une image fidèle."},{"t":"cpt","q":"Comment prépare-t-on un cycle de révision achats fournisseurs ?","r":"On rapproche la balance auxiliaire du compte collectif, on analyse les soldes anormaux, on teste le cut-off des factures non parvenues, puis on justifie chaque solde ancien ligne par ligne.","x":"Le mot cycle revient dans toutes les annonces de comptable et d'auditeur. Sache en dérouler un de bout en bout sans hésiter."},{"t":"cpt","q":"Qu'est-ce qu'une balance auxiliaire et pourquoi on la rapproche ?","r":"C'est le détail des comptes par client ou par fournisseur. Son total doit égaler le solde du compte collectif de la balance générale. Un écart signale une écriture passée directement sur le collectif.","x":"Contrôle de trente secondes qui attrape les erreurs les plus bêtes. À citer comme exemple de contrôle de premier niveau."},{"t":"cpt","q":"Qu'est-ce qu'une feuille maîtresse dans un dossier de révision ?","r":"Une page par cycle avec le solde de l'exercice, celui de l'exercice précédent, la variation et son explication, plus le renvoi vers les justificatifs.","x":"C'est ce qu'un associé regarde en premier. Si la variation n'est pas expliquée en une ligne, le travail n'est pas fini."},{"t":"conso","q":"Qu'est-ce qu'un package de consolidation ?","r":"Le formulaire que chaque filiale remplit avec ses comptes retraités aux normes du groupe et le détail de ses opérations intragroupe.","x":"En entretien consolidation, dis que la qualité du package fait la vitesse de la conso. Les retards viennent toujours des filiales."},{"t":"conso","q":"Comment traite-t-on des comptes réciproques qui ne se rapprochent pas ?","r":"Chaque filiale déclare ce qu'elle doit et ce qu'on lui doit. On confronte les deux déclarations, on explique l'écart, souvent une facture en transit ou une différence de date, et on impose l'écriture à celle qui a tort.","x":"Un seuil de tolérance est fixé au départ, mille euros par exemple. En dessous, on passe l'écart en résultat et on avance."},{"t":"tres","q":"Sur quoi repose une analyse de risque client avant d'ouvrir un encours ?","r":"Trois sources : les comptes publiés avec la rentabilité et les fonds propres, l'historique de paiement chez nous, et un avis externe comme une note d'assurance-crédit.","x":"Poste d'analyste crédit très demandé. La bonne réponse se termine toujours par une limite chiffrée et une date de revue."},{"t":"tres","q":"Qu'est-ce qu'une cotation Banque de France ?","r":"Une note attribuée aux entreprises : un chiffre pour la taille du chiffre d'affaires, puis une cote de crédit allant de 3++ à 9 qui juge la capacité à tenir ses engagements à trois ans.","x":"3++ est la meilleure, 9 signale un incident de paiement grave. Les banques s'en servent pour accorder ou refuser un crédit."},{"t":"tres","q":"Comment fonctionne l'affacturage et que coûte-t-il vraiment ?","r":"Le factor achète les factures et avance le cash. Deux coûts : une commission d'affacturage sur le montant cédé, et une commission de financement au taux annuel sur la durée d'avance. S'ajoute un fonds de garantie retenu puis rendu.","x":"Le fonds de garantie n'est pas un coût, mais il réduit le cash reçu tout de suite. C'est la confusion la plus fréquente."},{"t":"data","q":"Qu'est-ce qu'un flux d'interface entre un ERP et un outil de reporting ?","r":"Une extraction automatique qui reprend les écritures de l'ERP et les charge dans l'outil de pilotage, chaque nuit ou après chaque clôture.","x":"Le contrôle à connaître : le total chargé doit égaler le total de la balance. Sinon on pilote sur des données incomplètes sans le savoir."},{"t":"cdg","q":"Que veut dire structurer un reporting dans une annonce ?","r":"Poser un format stable, une source unique par chiffre, un calendrier de production et un responsable par ligne. L'automatisation vient après, jamais avant.","x":"Le mot structuration revient partout cette année. Il veut dire que le poste est à construire et pas seulement à tenir. Bonne nouvelle pour un junior."},{"t":"cdg","q":"Qu'est-ce qu'un budget flexible ?","r":"Un budget recalculé au niveau d'activité réellement atteint. On compare ensuite le réel à ce budget-là, pas au budget d'origine.","x":"C'est ce qui sépare l'écart dû au volume de l'écart dû à la gestion. Réponse qui marque des points en entretien de contrôle de gestion."},{"t":"cdg","q":"Comment reconnaît-on le chiffre d'affaires d'un chantier à l'avancement ?","r":"On mesure l'avancement par les coûts engagés rapportés au coût total estimé, puis on applique ce pourcentage au prix de vente du chantier.","x":"Méthode attendue dans toute annonce de contrôle de gestion projets ou BTP. Le point à dire : l'avancement se mesure en coûts, pas en jours écoulés."},{"t":"cdg","q":"Qu'est-ce que le reste à faire sur un projet ?","r":"Ce qu'il reste vraiment à dépenser pour finir, réestimé à neuf par le chef de projet. Ce n'est pas le budget non consommé.","x":"La question du contrôle de gestion projets. Le budget restant est un solde comptable, le reste à faire est une prévision. Confondre les deux masque toutes les dérives."},{"t":"cdg","q":"Qu'est-ce qu'une marge à terminaison ?","r":"Le prix de vente du projet moins le coût à terminaison, c'est-à-dire les coûts déjà engagés augmentés du reste à faire.","x":"On la suit à chaque point mensuel. Sa dérive est le premier signal d'alerte sur une affaire, bien avant que la perte n'apparaisse en comptabilité."},{"t":"cdg","q":"Que fait-on quand un projet passe en perte à terminaison ?","r":"On provisionne immédiatement la perte totale à venir, sans attendre qu'elle se réalise, et on la documente ligne par ligne.","x":"Règle de prudence et question fréquente en entretien BTP ou ingénierie. Le contrôleur de gestion la déclenche, le comptable la passe."},{"t":"cdg","q":"Comment refacture-t-on des coûts centraux à des filiales ?","r":"On choisit une clé objective, effectif, chiffre d'affaires ou surface, on la fige en début d'année, et on refacture le coût réel au prorata de cette clé.","x":"Postes de contrôleur de gestion coûts centraux. Le point qui marque : la clé se fige, sinon la filiale qui embauche paie plus sans avoir rien décidé."},{"t":"cdg","q":"Qu'est-ce qu'une économie achats et comment la mesure-t-on ?","r":"L'écart de prix entre l'ancien et le nouveau contrat, appliqué au volume de l'année précédente, donc à volume constant.","x":"Si on laisse le volume bouger, une baisse d'activité se lit comme une performance achat. Le contrôleur de gestion est là pour l'empêcher."},{"t":"cdg","q":"Qu'est-ce qu'une unité d'oeuvre en logistique ?","r":"L'unité qui porte le coût : la palette, la ligne de commande, le colis ou la tonne kilomètre. On divise le coût de la structure par son volume.","x":"Postes de contrôle de gestion logistique et transport. Sache en citer deux et dire laquelle tu choisirais selon l'activité, et pourquoi."},{"t":"cdg","q":"Comment refacture-t-on un budget informatique aux directions ?","r":"On divise le budget par le nombre de postes pour obtenir un coût par utilisateur, puis on l'applique à l'effectif de chaque direction.","x":"Poste de contrôleur de gestion IT. Le point de méthode : un coût unique fait payer pareil un poste bureautique et un poste d'ingénieur. Dès que l'écart de service est gros, il faut deux unités d'oeuvre."},{"t":"cdg","q":"Qu'est-ce que l'effet report sur la masse salariale ?","r":"Le coût en année pleine d'une augmentation accordée en cours d'année précédente, diminué de ce qui a déjà été payé l'an dernier.","x":"Il tombe dans le budget de l'année sans qu'aucune décision nouvelle ne soit prise. Première chose à isoler dans un budget de masse salariale."},{"t":"cdg","q":"Qu'est-ce que l'effet GVT ?","r":"Le glissement vieillesse technicité : la dérive naturelle de la masse salariale à effectif constant, par les promotions, l'ancienneté et les changements de poste.","x":"Vocabulaire du contrôle de gestion sociale. Il se distingue de l'augmentation générale, qui est une décision, alors que le GVT se subit."},{"t":"cdg","q":"Qu'est-ce qu'un rolling forecast ?","r":"Une prévision glissante, réactualisée chaque mois ou chaque trimestre sur un horizon fixe, souvent douze mois.","x":"Mot qui revient dans les annonces FP&A. Dis qu'il complète le budget, il ne le remplace pas, sinon plus personne ne porte son écart."},{"t":"audit","q":"Que sont les trois lignes de maîtrise ?","r":"Les opérationnels qui portent le risque, les fonctions de contrôle et de conformité qui l'encadrent, et l'audit interne qui donne une assurance indépendante.","x":"Modèle attendu dès qu'une annonce parle d'audit interne ou de conformité. Sache dire à quelle ligne se situe le poste pour lequel tu postules."},{"t":"audit","q":"Qu'est-ce qu'une cartographie des risques ?","r":"Un inventaire des risques cotés sur deux axes, la probabilité et l'impact, qui sert à bâtir le plan d'audit de l'année.","x":"L'audit interne ne teste pas tout. Il teste ce que la cartographie a classé en haut à droite. C'est la réponse à la question sur la priorisation."},{"t":"audit","q":"Quelle différence entre un test de cheminement et un test d'efficacité ?","r":"Le cheminement suit une opération de bout en bout pour comprendre le processus. Le test d'efficacité vérifie sur un échantillon que le contrôle a fonctionné toute l'année.","x":"Le premier décrit, le second prouve. Les confondre est l'erreur classique en entretien d'audit."},{"t":"audit","q":"Qu'est-ce qu'une recommandation d'audit bien écrite ?","r":"Un constat chiffré, sa cause, le risque qu'il fait courir, une action précise, un responsable nommé et une date.","x":"Sans responsable ni date, une recommandation n'est jamais mise en oeuvre. C'est le suivi qui fait la valeur de l'audit interne, pas le rapport."},{"t":"audit","q":"Qu'est-ce que le risque de non détection ?","r":"La probabilité que l'auditeur ne repère pas une anomalie significative. C'est le seul des trois risques qu'il pilote, en augmentant ses tests.","x":"Formule à connaître par coeur : risque d'audit égale risque inhérent fois risque de contrôle fois risque de non détection."},{"t":"audit","q":"Qu'est-ce qu'un sondage en unités monétaires ?","r":"Un tirage au fil de l'euro : chaque euro de la population a la même chance d'être pris, donc les grosses lignes sortent presque toujours.","x":"Méthode standard sur les créances et les achats. Elle concentre le test là où le montant est, pas là où le nombre de lignes est."},{"t":"audit","q":"Quelle différence entre audit interne et contrôle interne ?","r":"Le contrôle interne est le dispositif qui tourne tous les jours dans l'entreprise. L'audit interne est la fonction qui vient vérifier que ce dispositif marche.","x":"Question de première minute en entretien d'audit interne. L'un est l'objet, l'autre est le regard porté dessus."},{"t":"cpt","q":"Que fait un comptable général dans un environnement multi normes ?","r":"Il tient les comptes en normes locales et prépare à côté les retraitements IFRS demandés par le groupe, dans une liasse séparée.","x":"Annonces de comptable général international. Le mot à placer : la comptabilité locale reste la référence fiscale, l'IFRS sert la publication du groupe."},{"t":"cpt","q":"Comment solde-t-on un écart de réconciliation intragroupe ?","r":"On cherche les factures en transit, les avoirs passés d'un seul côté et les écarts de change, puis chaque entité corrige de son côté.","x":"Ne jamais forcer d'un seul côté. Ce qui reste inexpliqué après analyse se remonte, il ne s'absorbe pas dans un compte d'attente."},{"t":"cpt","q":"Quelle différence entre une provision et une charge à payer ?","r":"La charge à payer a un montant et une échéance connus, seule la facture manque. La provision porte sur un montant ou une date incertains.","x":"Question fréquente en entretien de comptabilité. Un litige se provisionne, la facture de téléphone de décembre est une charge à payer."},{"t":"cpt","q":"Qu'est-ce qu'une perte de change latente ?","r":"L'écart défavorable constaté à la clôture sur une créance ou une dette en devise encore ouverte. Elle se provisionne, elle n'est pas réalisée.","x":"La perte réalisée passe au résultat au moment du paiement. La latente passe par un écart de conversion actif et une provision pour risque."},{"t":"af","q":"Qu'est-ce que le DSCR dans un financement de projet ?","r":"Le flux de trésorerie disponible de la période divisé par le service de la dette, capital et intérêts compris.","x":"Ratio central des annonces de financement de projet. En dessous de 1, le projet ne paie pas sa dette avec ses propres flux."},{"t":"cf","q":"Qu'est-ce qu'une dette sans recours ?","r":"Une dette remboursée par les seuls flux du projet financé. Le prêteur n'a pas de recours sur le bilan de l'actionnaire.","x":"Le coeur du financement de projet. C'est ce qui explique que le prêteur exige un DSCR élevé et des sûretés sur les contrats du projet."},{"t":"cf","q":"Quand préfère-t-on les multiples au modèle DCF ?","r":"Quand on dispose de comparables cotés ou de transactions récentes, et quand les flux futurs sont trop incertains pour être projetés sérieusement.","x":"Postes d'évaluation financière. La bonne réponse en entretien : on fait les deux et on explique l'écart, on ne choisit pas l'un contre l'autre."},{"t":"cf","q":"Que regarde-t-on en premier dans une due diligence financière ?","r":"La qualité de l'EBITDA : les éléments non récurrents, les retraitements normatifs, et la dette nette réellement ajustée.","x":"Vocabulaire des équipes transaction services. Les deux mots à placer sont EBITDA normatif et dette nette ajustée."},{"t":"conso","q":"Pourquoi retraite-t-on un crédit-bail en consolidation ?","r":"Pour montrer le bien à l'actif et la dette au passif, comme si le groupe l'avait acheté. La redevance cède la place à un amortissement et à des intérêts.","x":"L'effet sur le résultat est faible, l'effet sur l'EBITDA et sur la dette nette est majeur. C'est exactement là que le lecteur regarde."},{"t":"conso","q":"Qu'est-ce qu'un retraitement d'homogénéité en consolidation ?","r":"L'alignement des méthodes comptables des filiales sur celles du groupe, par exemple une durée d'amortissement ou une méthode de valorisation des stocks.","x":"Étape juste avant les éliminations. Une annonce de consolideur la cite souvent sous le nom de retraitements de préconsolidation."},{"t":"data","q":"Qu'est-ce qu'un modèle en étoile dans Power BI ?","r":"Une table de faits au centre, qui porte les chiffres, entourée de tables de dimensions qui portent les axes d'analyse, reliées par une clé unique.","x":"Annonces qui demandent Power BI. Dis que tu évites les relations de plusieurs à plusieurs, c'est ce qui casse les totaux sans prévenir."},{"t":"data","q":"À quoi sert un GROUP BY en SQL ?","r":"À agréger des lignes par une ou plusieurs colonnes, pour sortir une somme, un compte ou une moyenne par axe d'analyse.","x":"Niveau attendu d'un contrôleur de gestion, pas d'un développeur. Savoir lire une requête et vérifier un total suffit dans la plupart des postes."},{"t":"tres","q":"Qu'est-ce qu'un cash pooling ?","r":"La centralisation des soldes bancaires des filiales sur un compte pivot, soit par virement réel, soit par simple fusion des échelles d'intérêts.","x":"Annonces multi entités. Le point à connaître : les mouvements créent des comptes courants intragroupe, à rémunérer et à justifier chaque année."},{"t":"meta","q":"Comment dit-on écart budgétaire en anglais ?","r":"Budget variance. L'écart favorable se dit favourable variance, l'écart défavorable adverse variance ou unfavourable variance.","x":"L'anglais est cité dans une annonce sur trois. Apprends dix mots du reporting, pas une grammaire : accruals, forecast, headcount, variance, run rate."},{"t":"meta","q":"Que répondre à pourquoi le contrôle de gestion et pas la comptabilité ?","r":"La comptabilité dit ce qui s'est passé, le contrôle de gestion dit pourquoi et ce qu'on fait ensuite. Je veux être là où la décision se prend.","x":"Question posée presque à chaque fois quand on vient d'un profil comptable. Réponse courte, et surtout aucun dénigrement de la comptabilité."}]};
